/* ===== Core: navigation, toast ===== */
const $=id=>document.getElementById(id);
const VIEWS=['map','gunsmith','gear','traits','dynops','loot','bosses','upgrades','camos','patches','items','upgradeitems','schematics','manuals'];
const toastEl=$('toast');let toastT;
function toast(msg){clearTimeout(toastT);toastEl.textContent=msg;toastEl.classList.add('show');toastT=setTimeout(()=>toastEl.classList.remove('show'),2400)}
const inits={};const ready={};
const PATHS={map:'/map/',gunsmith:'/gunsmith/',gear:'/gear/',traits:'/traits/',dynops:'/dynamic-ops/',loot:'/loot/',bosses:'/boss-strats/',upgrades:'/upgrades/',camos:'/camo-tracker/',patches:'/patch-notes/',items:'/items/',upgradeitems:'/upgrade-items/',schematics:'/schematic-tracker/',manuals:'/weapon-manual-tracker/'};
function parseRoute(){
  let seg=location.pathname.split('/').filter(s=>s&&s!=='index.html');
  if(!seg.length&&location.hash.length>1)seg=location.hash.slice(1).split('/').filter(Boolean);
  let v=seg[0]||'';if(v==='dynamic-ops')v='dynops';if(v==='boss-strats')v='bosses';if(v==='camo-tracker')v='camos';if(v==='patch-notes')v='patches';if(v==='upgrade-items')v='upgradeitems';if(v==='schematic-tracker')v='schematics';if(v==='weapon-manual-tracker')v='manuals';
  const view=VIEWS.includes(v)?v:null;
  return {view,arg:view==='items'?new URLSearchParams(location.search).get('i'):seg[1]};
}
function routePath(view,arg){if(view==='items')return '/items/'+(arg?'?i='+encodeURIComponent(arg):'');return view?PATHS[view]+(arg?arg+'/':''):'/'}
function setMeta(path){
  const m=(window.PAGE_META||{})[path];if(!m)return;
  document.title=m.t;const d=document.querySelector('meta[name="description"]');if(d)d.setAttribute('content',m.d);
  const cn=document.querySelector('link[rel="canonical"]');if(cn)cn.setAttribute('href','https://nomaddmzhub.com'+path);
}
function render(){
  const {view,arg}=parseRoute();
  VIEWS.forEach(n=>$('screen-'+n).classList.toggle('active',n===view));
  document.body.classList.toggle('in-module',!!view);
  $('home').inert=!!view;
  if(window.tileProgress&&!view)tileProgress();if(window.navActive)navActive(view);
  if(view!=='map'&&window.mapClearRoute)mapClearRoute();
  hideTip();
  if(view&&!ready[view]&&inits[view]){inits[view]();ready[view]=true}
  if(view==='map'&&window.mapLayout)mapLayout();
  if(view==='upgradeitems'&&window.upItemsRender)upItemsRender();
  if(view==='loot'&&window.lootShow)lootShow(arg);
  if(view==='bosses'&&window.bossShow)bossShow(arg);
  if(view==='upgrades'&&window.upShow)upShow();
  if(view==='manuals'&&window.wmRender&&ready.manuals)wmRender();
  if(view==='camos'&&window.camoShow)camoShow();
  if(view==='traits'&&window.trTabsReset)trTabsReset();
  if(view==='patches'&&window.patchShow)patchShow();
  if(view==='items'&&window.itemsShow)itemsShow(arg);
  if(!view){const last=document.querySelector('[data-open="'+lastView+'"]');if(last)last.focus({preventScroll:true})}
  if(view)lastView=view;
  if(!(view==='items'&&arg))setMeta(view==='items'?'/items/':routePath(view,arg));
}
let lastView=null;
function openView(v){
  const [n,a]=v.split('/');const path=routePath(n,a);
  if(location.pathname+location.search===path&&!location.hash)return;
  history.pushState({hub:true},'',path);render();window.scrollTo(0,0);
}
function goHome(){
  if(location.pathname==='/'&&!location.hash)return;
  history.pushState({hub:true},'','/');render();window.scrollTo(0,0);
}
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',e=>{if(b.tagName==='A'){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button)return;e.preventDefault()}openView(b.dataset.open)}));   // links open instantly; Ctrl/middle-click still opens a new tab
document.querySelectorAll('[data-home]').forEach(b=>b.addEventListener('click',e=>{if(b.tagName==='A'){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button)return;e.preventDefault()}goHome()}));
window.addEventListener('popstate',render);
window.addEventListener('hashchange',render);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const cd=$('camoDlg');if(cd&&!cd.hidden){cd.hidden=true;if(window.camoClose)camoClose();return}const pd=$('prestDlg');if(pd&&!pd.hidden){pd.hidden=true;return}const md=$('minorDlg');if(md&&!md.hidden){md.hidden=true;return}const dg=$('ingDlg');if(dg&&!dg.hidden){dg.hidden=true;return}const lb=$('lightbox');if(!lb)return;if(!lb.hidden){lb.hidden=true;return}if(location.hash&&!document.body.classList.contains('rail-open'))goHome()}});

/* ===== Floating tooltip (traits) ===== */
const tipEl=$('tip');
function showTip(el,html,color){
  tipEl.innerHTML=html;tipEl.style.setProperty('--c',color||'var(--gold)');tipEl.classList.add('show');
  const r=el.getBoundingClientRect(),t=tipEl.getBoundingClientRect(),m=10;
  let x=r.left+r.width/2-t.width/2,y=r.top-t.height-m;
  if(y<m)y=r.bottom+m;
  x=Math.max(m,Math.min(x,innerWidth-t.width-m));
  if(y+t.height>innerHeight-m)y=Math.max(m,innerHeight-t.height-m);
  tipEl.style.left=x+'px';tipEl.style.top=y+'px';
}
function hideTip(){tipEl.classList.remove('show')}
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));


