const PRESTIGE_TRAITS=[{"id":"adaptive-restock","n":"Adaptive Restock Pro","tree":"warfighter","d":"Enemy hostiles drop rarer additional items.","ic":"/img/pt-adaptive-restock.webp?v=52e08b60"},{"id":"possum","n":"Possum Pro","tree":"warfighter","d":"Allows a Self Revive into Last Stand from death, and removes the tourniquet health penalty, once per match.","ic":"/img/pt-possum.webp?v=36151fe1"},{"id":"quick-fix","n":"Quick Fix Pro","tree":"warfighter","d":"Immediately begin health regeneration when an enemy operator or hostile is killed.","ic":"/img/pt-quick-fix.webp?v=14e0e083"},{"id":"viper-sense","n":"Viper Sense Pro","tree":"warfighter","d":"Conceals you from thermal optics and AI targeting systems. Also alerts you when an enemy Operator is aiming at you.","ic":"/img/pt-viper-sense.webp?v=08f8dd4e"},{"id":"overwatch","n":"Overwatch Pro","tree":"scout","d":"UAV towers you activate never expire. Also increases their range.","ic":"/img/pt-overwatch.webp?v=b64d087f"},{"id":"uav-upgrade","n":"UAV Upgrade Pro","tree":"scout","d":"Increases the range and duration of UAVs and upgrades them to Advanced UAVs. Also expands your minimap.","ic":"/img/pt-uav-upgrade.webp?v=a5a3c292"},{"id":"thermal-padding","n":"Thermal Padding Pro","tree":"scout","d":"Enhances Thermal Padding to hide occupied vehicles from UAV detection.","ic":"/img/pt-thermal-padding.webp?v=dd680ee7"},{"id":"field-crafting","n":"Field Crafting Pro","tree":"scout","d":"Allows crafting items directly out of Common printer resources while deployed, and reduces the resource cost of each craft by 50%.","ic":"/img/pt-field-crafting.webp?v=eb441d75"},{"id":"free-revive","n":"Free Revive Pro","tree":"survivalist","d":"Automatically repairs your first Wound. Also allows you to tourniquet while Wounded.","ic":"/img/pt-free-revive.webp?v=5871021c"},{"id":"numb-the-pain","n":"Numb the Pain Pro","tree":"survivalist","d":"Upgraded version of Numb the Pain. Its exact effect is not confirmed yet.","ic":"/img/pt-numb-the-pain.webp?v=d5b4817a"},{"id":"impact-smokes","n":"Impact Smokes Pro","tree":"survivalist","d":"Increases size and duration of smoke released for Impact Smokes.","ic":"/img/pt-impact-smokes.webp?v=429866ff"},{"id":"die-hard","n":"Die Hard Pro","tree":"survivalist","d":"Approaching an exfil while in Last Stand calls the exfil automatically. Also grants infinite bleed out time and faster movement speed while in Last Stand.","ic":"/img/pt-die-hard.webp?v=ff965503"}];

const DYN_OPS=[{"n":"Viral Reckoning","t":"Scientist rescue / WMD sabotage","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 4,230; completion 4,950","v":"HVT-radio opening and UAV opening; continuation after scientist rescue.","d":"Codes change; use the active objective. Plan who carries and who provides cover.","s":["Get scientist intel: marked HVT and radio, or assigned UAV-intel interaction.","Reach the scientist and unlock the room using the current objective code.","Carry scientist to the landing zone; defend until the helicopter arrives.","Put the scientist in the helicopter.","Choose the offered partial-credit exfil or continue to collect the explosive.","Plant the explosive on the assigned biological WMD and confirm completion."]},{"n":"Ghost Shipment","t":"HVT / SAM interception","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 4,500; completion 4,950","v":"Cargo recovery can follow aircraft destruction.","d":"Wait for Operation Complete; do not leave just because the aircraft is down. Keep ammunition for SAM defence.","s":["Eliminate the marked HVT.","Pick up Classified Orders; the kill alone is not the intel pickup.","Approach the assigned SAM site; capture and defend it.","Wait for the aircraft objective to resolve.","Loot the marked Lieutenant cargo container when the tracker requests it."]},{"n":"Chemical Denial","t":"Chemical crafting OR server defence","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 3,000; completion 3,300","v":"The chemical-crafting and power/hack/defend routes are alternatives.","d":"Components: Volatile Glutaraldehyde, Potent Acetic Anhydride, Crude Diethyl Ether. Do not treat both route alternatives as mandatory.","s":["Craft route: retrieve the marked item, as Classified Documents.","Collect three assigned chemical mission components.","Use Craft Compound at the marked workbench.","Deposit the Unstable Compound in the assigned case; move clear and confirm completion.","Alternative server route: turn on power, hack the Comms Server, protect the transfer, then confirm completion."]},{"n":"Toxic Intercept","t":"Decryption / fuel / vehicle delivery","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 4,500; completion 4,950","v":"A drive-to-tanker route exists; other versions mention bomb defence.","d":"Use mission-marked objects.","s":["Recover the encrypted drive from the assigned cache.","Decrypt at the marked enemy computer.","Defend the transfer until the tracker advances.","Use Request a Fuel Resupply at the assigned UAV tower.","Hijack the marked tanker.","Deliver it to the assigned destination; confirm the required interaction and completion."]},{"n":"Dead Man's Cache","t":"Intel / cache demolition / HVT","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 4,500; completion 5,146","v":"Intel openings and bomb containers vary.","d":"Destroying the cache can be an intermediate objective. Finding a container is not the same as taking the mission item.","s":["Complete the assigned intel opening: cache, encrypted-drive or enemy-comms variant.","Complete the keypad or terminal stage if assigned; use current code.","Download the target cache location.","Collect the marked mission bomb.","Destroy the assigned ammunition/armour cache.","Continue to the HVT objective when shown; eliminate it and confirm completion."]},{"n":"Signal Breaker","t":"Bomb crafting / multiple sabotage targets","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 6,000; completion 6,600","v":"Part containers and target assignments vary.","d":"Collection and planting use separate 0/3 counters. Ordinary printer resources or the FOB printer do not replace the mission workbench.","s":["Collect all three assigned mission bomb parts.","Craft the bomb at the marked field workbench.","Plant at each of three assigned radar-truck targets.","Confirm operation completion after the final target."]},{"n":"Broken Resupply","t":"Hack / safe intel / WMD sabotage","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 2,993; completion 3,496","v":"Bomb containers and keypad codes differ.","d":"Do not add unrelated Lieutenant or SAM objectives from elsewhere on the HUD to this operation checklist.","s":["Hack the assigned Comms Server.","Defend until that stage completes.","Retrieve the marked bomb from the assigned container.","Open the assigned safe to obtain keypad intel.","Unlock the marked room using the current code.","Plant on the WMD; move clear and confirm completion."]},{"n":"Special Delivery","t":"Bomb crafting / launcher destruction","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 4,500; completion 5,048","v":"Laptop upload and UAV capture alternatives.","d":"Mission bomb parts are not ordinary crafting materials. Planting alone does not complete the defence or detonation checks.","s":["Collect three bomb components: Explosives, Explosives Wiring, Explosives Numpad in the documented route.","Craft the bomb at the field workbench.","Complete the assigned laptop upload OR UAV capture stage.","Reach the marked Mobile Launch Platform.","Plant the bomb and complete the defence.","Take cover and wait for detonation/completion."]},{"n":"Domino Protocol","t":"Linked HVTs / Lieutenant hunt","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 8,000; completion 6,500","v":"Assigned targets and the final Lieutenant vary.","d":"Lieutenant dog-tag cash is separate and requires extraction.","s":["Eliminate first HVT and collect Classified Documents.","Eliminate second HVT and collect its intel.","Follow the resulting Lieutenant objective.","Defeat the assigned Lieutenant; confirm operation completion."]},{"n":"Sky Heist","t":"Intel / aircraft theft","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"An unfinished run gave about 500 XP at extraction; no completion figure yet.","v":"Intel openings vary; a separate helicopter-hacking alternative .","d":"The pilot key is a mission item, not a reusable stash key. One flight timer example was about 3:45; use the live timer. Check parachutes before choosing to jump.","s":["Complete the assigned intel opening: safe/cache/locker or power-terminal route.","Complete a SAM stage if the tracker assigns one.","Eliminate the marked pilot and collect the helicopter mission key.","Unlock the assigned heavy helicopter.","Follow the live timed flight/exfil objective.","Read the leave/extract options and current completion state before deciding whether to stay aboard."]},{"n":"Hunt Operator","t":"Target hunt","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Panel 6,000; completion 6,150","v":"Named wanted target versus rival-squad hunt.","d":"A 5,000 target bounty can be paid separately from the operation reward.","s":["Read the target identity and objective on the current tracker.","Eliminate the assigned target or squad as specified.","Confirm completion before treating the hunt as finished."]},{"n":"Ignition Point","t":"Reach target area","start":"Dynamic Operations deploy mode or activate a field phone","cash":null,"xp":"Completion 3,000","v":"Only a short reach-area route exists.","d":"","s":["Proceed to the marked target area.","Confirm the operation-completion message; follow any additional objectives actually shown."]}];
const DYN_RULES=[["Starting","Choose Dynamic Operations deployment, or activate a live Dynamic Op phone. The active tracker decides the chain you are assigned."],["One at a time","Only one Dynamic Op is active at once. Cancel from the Tac Map to change, and complete more as time permits."],["Rewards","A completed Op gives cash, XP and a supply drop. Within one deployment the supply drops step up: Common, Uncommon, Rare."],["Crate trait","Objective Oriented improves an Op reward crate by one tier, up to Rare."],["Cash","Each Op pays 10,000 to 20,000 DMZ Cash (raised from 5,000–10,000 on 30 October). The exact amount varies from run to run. The same update raised Side Ops to 2,000 Cash and Mission Steps to 500 Cash per step."],["Mission items","Bomb components, intel and pilot keys are operation items. Field mission crafting is separate from the ordinary FOB printer recipes."]];

const LOOT_SPOTS=[{"id":"irradiated-items","name":"How to open irradiated items","type":"How to","place":"Haneul Nuclear Reactor","map":"Haneul Nuclear Reactor","title":"How to Open Irradiated Items in DMZ (Haneul Nuclear Reactor Guide)","desc":"Found an irradiated item in MW4 DMZ? Here is how to get into the Haneul Nuclear Reactor, reach the processing machine and open it for a chance at gear.","summary":"Found an irradiated item? Take it to the processing machine inside the Haneul Nuclear Reactor for a chance at gear.","intro":"Found an irradiated item in DMZ? Keep it. You can take it to the Haneul Nuclear Reactor and process it for a chance at some gear.","hero":{"src":"/img/loot-irradiated-zone-map.webp?v=3a8e4b71","url":"/loot-img/irradiated-zone-map.webp","alt":"The Haneul Nuclear Reactor and its radiation zone on the Hajin map","cap":"The Haneul Nuclear Reactor radiation zone on the map"},"find":[],"steps":[{"h":"Before you go in","p":"Bring gas masks if you have them. The reactor is a radiation zone, so go in prepared. Gas masks no longer break as soon as you enter radiation, so one lasts the run. If you haven't got a mask, the bots around the facility can drop them. A hazmat suit can also spawn inside."},{"h":"Finding the way in","p":"Head to the second reactor on the right and look for the broken staircase at the back. Climb up to the upper level, take the ladder, then jump across the gap to the next section.","img":{"src":"/img/loot-irradiated-reactor-map.webp?v=ed644698","url":"/loot-img/irradiated-reactor-map.webp","alt":"Close-up map of the Haneul Nuclear Reactor buildings","cap":"The reactor buildings on the map"}},{"h":"Getting to the bottom","p":"Once you're across, climb the next ladder and work your way down through the reactor to the ground floor. Watch your footing on the way down. If you've got a parachute, you may be able to use it for a quicker descent."},{"h":"Processing your item","p":"Look for the processing machine in the corner on the ground floor. Walk up with your irradiated item and follow the prompt to put it in. Give it a few seconds to finish, then collect your loot.","img":{"src":"/img/loot-irradiated-machine.webp?v=5d4ec972","url":"/loot-img/irradiated-machine.webp","alt":"The irradiated item processing machine inside the reactor","cap":"The processing machine on the ground floor"}}],"tip":"Keep an eye out for spare gas masks and the hazmat suit while you're in there. They'll make the run easier."},{"id":"river-heights","name":"Hajin River Heights Compound","type":"Where to find","place":"Hajin River Heights","map":"Hajin River Heights","title":"Hajin River Heights Compound Loot Guide (MW4 DMZ)","desc":"Loot guide for the Hajin River Heights compound in MW4 DMZ: parking garage safe, roof safe, the Gangbyeon Apartment B Key and how to reach Building B.","summary":"Two buildings, multiple safes and plenty of loot. Weapon blueprints, gold bars and keys are possible.","intro":"Two buildings, multiple safes and plenty of loot.","hero":{"src":"/img/loot-river-heights-map.webp?v=4b8b730a","url":"/loot-img/river-heights-map.webp","alt":"The Hajin River Heights compound circled on the Hajin map","cap":"Hajin River Heights compound on the map"},"find":["A chance at weapon blueprints, gold bars and multiple keys","Green, purple and red supplies","Guaranteed weapons"],"steps":[{"h":"Start in the parking garage","p":"Head into the parking garage in the centre of the compound. Take a left at the bottom of the ramp and look for the safe. Loot that before heading to the apartments."},{"h":"Get into the first building","p":"Grab the vehicle from the garage or bring your own, then drive around the back of the apartment buildings. Facing the buildings from the rear, park beside the building on the left, directly under the overhead pipe. Jump onto the vehicle, then onto the pipe. Follow it along and climb through the window. Loot the room and unbolt the door from the inside to get into the rest of the building. Watch for bots inside."},{"h":"Find the key","p":"Search every room for the Gangbyeon Apartment B Key. Check shelves, beds, tables and dressers. It can spawn in different spots, so have a proper look before moving on.","img":{"src":"/img/loot-river-heights-key.webp?v=edff9801","url":"/loot-img/river-heights-key.webp","alt":"The Gangbyeon Apartment B Key on top of a dresser","cap":"The Gangbyeon Apartment B Key on a dresser"}},{"h":"Cross to Building B","p":"Once you've looted the first building and found the key, head to the roof and jump across to the neighbouring building. Loot the safe on the roof, then use the Gangbyeon Apartment B Key to open the locked rooftop access door."},{"h":"Loot up and get out","p":"Work your way through Building B and check the rooms for anything worth taking. Sort your bag, keep the good stuff and head for exfil with your GOOP."}],"tip":"Check both buildings properly. Between the garage safe, rooftop safe and apartment rooms, there's plenty to search."},{"id":"bunker-route","name":"Hajin Bunker Loot Route","type":"Where to find","place":"Western Hajin","map":"route","title":"Hajin Bunker Loot Route in MW4 DMZ: All Six Bunkers in Order","desc":"A six-stop loot route along the west side of Hajin in MW4 DMZ. See where each numbered bunker is and the best order to run them from north to south.","summary":"Six bunkers along the west side of Hajin. Run them 1 to 6 from north to south in one deployment.","intro":"There are six bunker markers along the west side of Hajin. This route links them in one north-to-south run, so you can search each one and decide at every stop whether to carry on or extract.","hero":{"src":"/img/loot-bunker-route.webp?v=a70f1623","url":"/loot-img/bunker-route.webp","alt":"Numbered route through the six bunkers on the west side of Hajin","cap":"The six bunkers on the map, in route order"},"find":[],"steps":[{"h":"Pick your end of the route","p":"Open the numbered map before you deploy and start at the end nearest your deployment. Stop 1 is in the north, above the 14th Political Prison. Stop 6 is the southernmost, on the western edge below Deadtown."},{"h":"Run it in order","p":"Travel to the next numbered marker, search the bunker, then decide whether to continue or extract. Stop 4 sits just west of the Chang-san Air Base, so expect company there."},{"h":"Check the map between stops","p":"The numbered map shows where the bunkers are. It does not show a safe path, active threats or extraction points, so check your tactical map before every move."},{"h":"Protect what you find","p":"Extract early when the risk of another stop outweighs what you might find there."}],"tip":"The route can be run in reverse. Start in the south if that is closer to your deployment.","route":[[1218,1428,"1"],[1554,1607,"2"],[1439,1820,"3"],[823,2216,"4"],[911,2658,"5"],[862,2868,"6"]],"layer":"silos"},{"id":"hanex-bank-vault","name":"How to open a Hanex bank vault","type":"How to","place":"Hanex banks","map":"layer:Bank","title":"How to Open a Hanex Bank Vault in MW4 DMZ: Car Battery, Access Card and Code","desc":"How to open a Hanex branch vault in MW4 DMZ: restore power with a Car Battery, find the vault access card, read the code note and open the keypad.","summary":"Car Battery, access card, code note, keypad. Here is how to get into a Hanex bank branch vault, and which banks it works at.","intro":"The Hanex branch vaults need three things: power, an access card and a code. Each is a separate stage, and the code changes every match, so there is no number to copy. Follow the steps in order and read the on-screen prompts as you go.","hero":{"src":"/img/loot-vault-flow.webp?v=a745624b","url":"/loot-img/vault-flow.webp","alt":"The four steps to open a Hanex bank branch vault: car battery, vault card, code note, keypad","cap":"The four stages of a Hanex branch vault"},"find":[],"steps":[{"h":"Go to a branch, not the tower","p":"The branch vaults are in the Hanex bank branches at Cheongun Village, Wolves Stadium, Songdo Wharf and South Hajin. The Vault Order names the Cheongun Village and Wolves Stadium branches. The Hanex Bank tower in The Grid is a different building."},{"h":"Find the sparking power panel","p":"Look for the sparking electrical panel inside the bank. It is often near the stairs or the basement, but read the on-screen prompt to be sure."},{"h":"Install a Car Battery","p":"Bring a Car Battery or find one on the way. Use it on the panel to restore power. Do not swap in another item unless the prompt accepts it."},{"h":"Search for the Bank Branch Vault Access card","p":"The card is a Rare item that spawns inside the branch. Its exact spot is random, so search the whole bank, including counters and desks."},{"h":"Use the card at the access reader","p":"The access reader is a separate stage from the vault keypad. Check power first if the reader does not respond."},{"h":"Read the code note","p":"Find the note inside the bank. It shows three digits of a four-digit code. Keep the digits in the order shown."},{"h":"Try the last digit","p":"Enter the three digits, then try 0 to 9 for the final one. Keep track of what you have tried. The code is different in every match, so never reuse one from another game."},{"h":"Loot and leave","p":"Take what you can carry, check your Order counter and extract. Loot varies from match to match."}],"tip":"Do not confuse the Bank Branch Vault Access card with the Hanex Guard Station key. The Guard Station key opens a guard room in the Hanex tower in The Grid. It does not open a branch vault."},{"id":"deadtown-waterfront-run","name":"Deadtown Waterfront Loot Run","type":"Where to find","place":"Deadtown","map":"route","route":[[1266,2881,"S"],[1228,2831,"1"],[1271,2789,"2"],[1330,2730,"3"],[1332,2699,"4"],[1224,2660,"5"]],"title":"Deadtown Waterfront Compound Loot Run in MW4 DMZ: 5-Stop Tech Loot Route","desc":"A compact 5-stop loot loop through the Deadtown waterfront compound in Hajin, hitting the best tech containers for Comms Modules and circuit boards.","summary":"A 5-stop road-led loop through the Deadtown waterfront compound, built around tech containers for Comms Modules and Electronics.","intro":"This is a short, road-led loop through the waterfront compound in Deadtown. It checks the buildings most likely to hold computers and other tech containers, without zig-zagging through every yard. Loot is random every match, so the route improves your chances but does not guarantee a particular item.","hero":{"src":"/img/loot-waterfront-run.webp?v=47ae8a31","url":"/loot-img/waterfront-run.webp","alt":"The five-stop loot run through the Deadtown waterfront compound on the Hajin map","cap":"The route from the waterfront start to stop 5"},"find":[],"steps":[{"h":"What to check first","p":"Go for computers and tech containers: gaming computers, UAV hatches, IT bags, server racks and computers. These are the best places to look for Comms Modules. Electronics come from tech loot you break down. For Printed Circuit Boards, follow the 3D Printer ingredient hint, because this compound is a bonus sweep for them."},{"h":"Start: waterfront staging","p":"Arrive from the shoreline road. Put your armour on and listen before you go into the compound."},{"h":"Stop 1: south buildings","p":"Work the two long southern buildings first. Clear the nearest one completely before you cross the open yard."},{"h":"Stop 2: roadside cluster","p":"Follow the central paved road north and check the small buildings beside it. Computers, bags, shelves and lockers come before general cash containers."},{"h":"Stop 3: east-side block","p":"Take the branch east into the building group. Check for threats before you commit, because this is where a team is most likely to hear you."},{"h":"Stop 4: north-east longhouse","p":"Sweep the long building and the small outbuildings around it. Leave once you have opened the last tech container."},{"h":"Stop 5: north-west road row","p":"Cross back along the top road and clear the buildings that face it. Reverse the route to extract, or cut the run short if you already have a high-value item."},{"h":"Rules for a clean extract","p":"Run the stops in order and do not cross the open centre twice for one missed container. Once you have a high-value item, switch from looting to survival."}],"tip":"Check the in-game 3D Printer ingredient hint before you deploy. It shows where each material is currently found."}];

const BOSS_STRATS=[{"id":"gorani","name":"Gorani","kind":"Lieutenant","subtitle":"The Forest Phantom","location":"Forest south of Cheonwang Peak Array","threat":"Camouflage, rifle fire, decoys, smoke and escort ambushes","loadout":"Scoped assault rifle, full armour, spare ammunition","steps":["Approach the woodland camp from cover and watch for camouflaged escorts.","Clear the guards before committing to Gorani himself.","Look for decoy targets and avoid emptying entire magazines into false targets.","Reposition around smoke without relying on it to stop incoming fire.","Identify the real Gorani, close the distance through cover and finish with sustained fire.","Check the surroundings before retrieving his dog tag."],"tip":"Don’t chase every figure in the smoke. Confirm the real target and use cover to close in.","rewards":"Dog Tag Case; possible MAR-9 / Incisor variant.","note":"The exact active encounter area can vary; confirm using intel or a Hunt Tower.","map":"Gorani"},{"id":"the-chemist","name":"The Chemist","kind":"Lieutenant","subtitle":"Reactor Radiation Boss","location":"Haneul Nuclear Reactor, eastern warehouse area","threat":"Radiation, hazmat guards, poor sightlines","loadout":"Gas mask, Radiation Blockers, full armour, assault rifle","steps":["Bring radiation protection before travelling to the reactor.","Approach the east-side warehouse and clear guards outside the entrances.","Move through the warehouse while watching the protection timer.","Identify the Chemist by his yellow protective suit and full-face mask.","Use automatic fire from the warehouse doorway or safe cover.","Loot quickly and retreat before your radiation protection expires."],"tip":"Plan for the entire entry, fight and exit—not just the boss kill—when budgeting radiation protection.","rewards":"Dog Tag Case; possible Revenant weapon and other crafting materials.","note":"consumable durations may change; check the current in-game item description.","map":"The Chemist"},{"id":"jin-tae","name":"Jin-Tae","kind":"Lieutenant","subtitle":"Casino Enforcer","location":"Heavenly Luck Casino, Cheongun Village","threat":"Heavy automatic fire across open gaming floor","loadout":"Assault rifle or LMG, grenades, armour plates","steps":["Enter the casino and locate his encounter marker.","Avoid staying exposed on the main gaming floor.","Fall back through the double doors into the staff/security offices.","Clear enemies advancing along the corridor.","Hold a protected angle and engage Jin-Tae as he comes through.","Replate before crossing the gaming floor to collect loot."],"tip":"The staff-office corridors make his otherwise exposed casino firefight much more manageable.","rewards":"Dog Tag Case; possible ISO Nightshade variant.","note":"Boss locations should be treated as encounter areas rather than guaranteed positions.","map":"Jin-Tae"},{"id":"the-doctor","name":"The Doctor","kind":"Lieutenant","subtitle":"Hospital Heavy","location":"Mirae General Hospital, wards / garage / grounds","threat":"Aggressive close-range pursuit","loadout":"Assault rifle, healing supplies, extra armour","steps":["Use active intel to track his current position within the hospital.","Clear nearby guards and identify doorways or stairs for retreat.","Maintain separation; do not let him close to point-blank range.","In a squad, spread out and fire from different safe angles.","Retreat, replate and re-engage as he advances.","Check for the key to his upper-floor Command Office."],"tip":"Make him chase you through a predictable doorway rather than fighting trapped in a small room.","rewards":"Dog Tag Case; possible Doctor’s Salve rifle and Command Office key.","note":"The Command Office is on the hospital’s upper floors.","map":"The Doctor"},{"id":"bale","name":"Bale","kind":"Lieutenant","subtitle":"The LMG Enforcer","location":"Re-Education Center, Deadtown; also near Chang-san Air Base","threat":"Sustained LMG fire and dangerous hallways","loadout":"Automatic rifle, armour, scoped secondary","steps":["Confirm which area is active before entering.","Clear the surrounding guards room by room.","Avoid sprinting down the corridor directly into Bale’s LMG.","Use side offices and doorways to establish a different firing angle.","In a squad, keep his attention on one position while a teammate flanks.","Damage him steadily and recover plates between pushes."],"tip":"Don’t challenge his LMG on a straight firing lane; change angles instead.","rewards":"Dog Tag Case; possible Type 73 / Dreadnought weapon.","note":"Bale can appear in more than one area, so use the encounter marker.","map":"Bale"},{"id":"iskra","name":"Iskra","kind":"Lieutenant","subtitle":"Stairwell Fighter","location":"Cheonwang Peak Array","threat":"Elevated gunfire, stairwell traps and close-range pressure","loadout":"Automatic rifle or LMG, spare armour","steps":["Clear the ground floor before advancing.","Find the internal stairs and expect contact above you.","Watch the landings for grenades or bursts of fire.","If pressured, retreat down a flight to replate.","Track Iskra’s movement as she may move down toward you.","Control the stairwell with automatic fire before approaching the body."],"tip":"Hold a protected staircase angle instead of blindly rushing the top landing.","rewards":"Dog Tag Case; possible Warlord shotgun and possible Control Room key.","note":"Key-room details should be checked against the latest game build.","map":"Iskra"},{"id":"the-scavenger","name":"The Scavenger","kind":"Lieutenant","subtitle":"The Roaming Hunter","location":"Variable; around Hajin River Heights and Cheongun Village","threat":"Unpredictable position, open sightlines and third parties","loadout":"Scoped assault rifle or marksman rifle","steps":["Use Lieutenant Hunt Tower intel or purchased intel to establish a live position.","Recon abandoned vehicles or the surrounding combat area before pushing.","Attack from a protected building corner or elevation.","Engage at medium range and use hard cover to reload.","Clear support enemies and watch for other squads drawn to the fight.","Secure the Dog Tag Case only after choosing an extraction route."],"tip":"Don’t rush his uncertain position; controlled medium-range fire is safer than crossing an exposed area.","rewards":"Dog Tag Case; possible ORIS 8.6 marksman rifle.","note":"No universally guaranteed spawn point has been confirmed.","map":"The Scavenger"},{"id":"roze","name":"Roze","kind":"Lieutenant","subtitle":"Rooftop Sniper","location":"DBN Headquarters rooftop, The Grid","threat":"High-damage sniper fire and potential aerial interference","loadout":"Scoped rifle, maximum armour, Self-Revive","steps":["Enter DBN Headquarters and clear the stairwell level by level.","Replate and reload before opening onto the roof.","Move behind HVAC units and rooftop structures.","Peek briefly, fire and reposition rather than holding one exposed angle.","Watch for the roaming Deathstalker while crossing open parts of the roof.","Loot quickly once the roof and nearby airspace are safe."],"tip":"Use short peeks and multiple angles; standing still on her roof is an easy way to get downed.","rewards":"Dog Tag Case; possible Astaroth .57 rifle.","note":"The area is Extreme-threat: other hostiles can be as dangerous as the boss.","map":"Roze"},{"id":"jang-ui","name":"Jang-ui","kind":"Lieutenant","subtitle":"Server Room Defender","location":"Netshin Tech Complex, The Grid; also around NuriGO Mall","threat":"Turrets, drones, guards and enclosed server halls","loadout":"High-capacity rifle or LMG, ammunition and armour","steps":["Follow the live Lieutenant marker to confirm the active building.","Clear corridor guards before crossing the server-room doorway.","Identify any turret or drone hazards first.","Use server racks and corners to break sightlines.","Apply sustained automatic fire and use openings for headshots.","Check for reinforcements before collecting loot."],"tip":"Disable or avoid building security before focusing your whole squad on Jang-ui.","rewards":"Dog Tag Case; possible Hyeon Burst / Paektu weapon.","note":"Floor numbers and encounter location differ across runs.","map":"Jang-ui"},{"id":"the-warden","name":"The Warden (Kang)","kind":"Lieutenant","subtitle":"Riot Shield Boss","location":"14th Political Prison / The Citadel","threat":"Riot shield, armoured guards, smoke-filled corridors","loadout":"Automatic rifles, tactical stuns/flashbangs, full armour","steps":["Clear the outside courtyard and guard positions.","Advance as a unit through the prison corridors to the mess hall.","Avoid wasting ammunition directly on the Warden’s shield.","Have one squad member draw his attention from the front.","Move another operator to his side or behind him and fire into exposed body areas.","Collect Kang’s Dog Tag after clearing the remaining guards."],"tip":"The shield makes this a positioning fight. Distract from the front and damage from the side.","rewards":"Kang’s Dog Tag; possible X-58 Nyx / Incarcerator weapon.","note":"His tag may be labelled Kang’s Dog Tag, not Warden’s Dog Tag.","map":"The Warden (Kang)"},{"id":"colossus","name":"Colossus","kind":"Commander","subtitle":"Armoured Minigun Commander","location":"Roams Hajin, including prison and airbase encounters","threat":"Minigun fire, electrical attacks, gas and heavy armour","loadout":"High-capacity LMG, spare ammunition, plates","steps":["Clear ordinary soldiers from the battlefield before engaging.","Select solid cover or a raised position with a fallback route.","Stay protected while the minigun fires; attack between bursts.","Use sustained automatic gunfire at visible upper-body and head areas.","Avoid electrical attacks by managing distance and changing positions.","Stay clear of gas produced during or after the fight."],"tip":"Sustained fire from cover is a more reliable baseline than betting everything on explosives. Drill Charges were weakened against Colossus on 25 October, so don't count on them.","rewards":"possible Military Composites and Experimental Compounds.","note":"Explosive effectiveness can vary between patches, so don't assume it is immune to every explosive.","map":null},{"id":"deathstalker","name":"Deathstalker","kind":"Commander","subtitle":"Autonomous Attack Aircraft","location":"Roams Hajin airspace","threat":"Aerial machine-gun attacks and moving firing angles","loadout":"Access to SAM Site, high-capacity rifle / anti-air backup","steps":["Locate the drone’s approximate position via the Tac-Map or Team Leader warning.","Choose a nearby SAM Site and clear its surrounding soldiers.","Capture the SAM Site by using the terminal and defending the hack.","Keep the Deathstalker close enough to be engaged by the site.","Use cover while the SAM fires; be prepared to re-engage if it escapes.","Search the wreckage after destruction."],"tip":"A captured SAM Site is the strongest documented tactical counter.","rewards":"possible Prototype RF Module and Drone Motherboard.","note":"The exact SAM engagement range and number of missiles may vary.","map":null},{"id":"nk-battle-tank","name":"Main NK Battle Tank","kind":"Commander","subtitle":"Armoured Vehicle Commander","location":"Roaming roads and highways across Hajin","threat":"Heavy cannon and reactive armour","loadout":"Rocket launcher, DDoS where available, Munitions Box","steps":["Identify the patrol route and choose substantial solid cover.","Avoid fighting from the centre of an exposed road.","Where applicable, use DDoS to disable reactive armour.","Hit the tank with rockets or other anti-vehicle damage.","Return behind cover after each shot to reload safely.","Resupply and repeat; inspect wreckage only after the area is secure."],"tip":"Bring enough anti-vehicle ammunition; no consistent rocket count is established.","rewards":"possible Nano-Structured Alloy and other Commander crafting materials.","note":"The Massive Damage Order involves a DDoS, rocket hit and tank destruction.","map":null}];

