    const entries=Object.entries(picks).sort((a,b)=>SLOT_ORDER.indexOf(a[0])-SLOT_ORDER.indexOf(b[0]));
    const n=entries.filter(e=>e[0]!=='Apex').length,cum=k=>GS_FEES.slice(0,k).reduce((s,x)=>s+x,0),money=v=>'$'+v.toLocaleString('en-AU');
    const slotFee=n>openSlots?cum(n)-cum(openSlots):0;let known=slotFee,unknown=0;const lines=[];
    const wp=owned?0:(weapon.price?dp(weapon.price):0);if(owned)lines.push(['Weapon (already owned)','$0']);else if(wp){known+=wp;lines.push(['Weapon',money(wp)])}else{unknown++;lines.push(['Weapon','<i>price not known</i>'])}
    if(n)lines.push(['New attachment slots ('+(n>openSlots?n-openSlots:0)+')',money(slotFee)]);
    entries.forEach(([slot,o])=>{const pr=(GS_PARTS[weapon.id]||{})[o.attachment_id];if(pr){const dpr=dp(pr);known+=dpr;lines.push([esc(o.attachment_name),money(dpr)])}else{unknown++;lines.push([esc(o.attachment_name),slot==='Apex'?'<i>part price not known</i>':'<i>price not known</i>'])}});
    box.innerHTML=`<div class="cart-head"><strong>Build cost</strong><label><input type="checkbox" id="gcOwn"${owned?' checked':''}> I already own this weapon</label><label>Your discount <input id="gcDisc" type="number" min="0" max="90" step="1" value="${disc}" class="gc-disc"> %</label><label>Slots already open <select id="gcOpen">${[0,1,2,3,4,5].map(i=>`<option${i===openSlots?' selected':''}>${i}</option>`).join('')}</select></label></div>
    <table class="cart-t"><tbody>${lines.map(l=>`<tr><td>${l[0]}</td><td>${l[1]}</td></tr>`).join('')}</tbody><tfoot><tr><td>${unknown?'Known so far':'Total'}</td><td><b>${money(known)}</b></td></tr></tfoot></table>
    <p class="cart-note">${unknown?unknown+' price'+(unknown>1?'s are':' is')+' not known, so the real total is higher. ':''}${disc?'Prices include your '+disc+'% discount on the weapon and parts. Slot fees are shown in full.':'These are base prices. Enter your own discount above to see what you pay. Slot fees are shown in full.'}</p>`;
    $('gcDisc').onchange=e=>setDisc(e.target.value);
