/* ===== UPGRADES TRACKER ===== */
(function(){
  const UPG=GEAR_DATA.find(g=>g.c==='Upgrades').r;
  const LINES=[];const romans=/ ([IVX]+)$/;
  UPG.forEach(t=>{const key=t.n.replace(romans,'');let L=LINES.find(l=>l.key===key);if(!L){L={key,tiers:[]};LINES.push(L)}L.tiers.push(t)});
  const st=()=>Store.get('upgrades');
  const done=L=>Math.min((st().done||{})[L.key]||0,L.tiers.length);
  /* one count per item, shared with the Full Upgrade Item List (s.stock). Older saves kept a count per tier (s.have): fold those in once */
  function migrate(){const s=st();if(!s.have||!Object.keys(s.have).length){delete s.have;return}s.stock=s.stock||{};
    LINES.forEach(L=>{const t=L.tiers[done(L)];const h=t&&s.have[t.n];if(h)Object.entries(h).forEach(([m,v])=>{if(+v>(s.stock[m]||0))s.stock[m]=+v})});delete s.have;Store.save()}
  window.upMigrate=migrate;
  const haveOf=(t,m)=>Math.max(0,Math.round(+((st().stock||{})[m]||0)));
  const setHave=(t,m,v)=>{const s=st();s.stock=s.stock||{};const n=Math.max(0,Math.min(1e9,Math.round(+v||0)));if(n)s.stock[m]=n;else delete s.stock[m];Store.save()};
  /* finishing a tier uses its items up; what was taken is kept so Undo can put it back */
  function spend(t){const s=st();s.stock=s.stock||{};s.spent=s.spent||{};const used={};reqs(t).forEach(r=>{const have=s.stock[r.m]||0,take=Math.min(have,r.need);if(take){used[r.m]=take;const left=have-take;if(left)s.stock[r.m]=left;else delete s.stock[r.m]}});if(Object.keys(used).length)s.spent[t.n]=used;else delete s.spent[t.n]}
  function refund(t){const s=st();const used=(s.spent||{})[t.n];if(!used)return;s.stock=s.stock||{};Object.entries(used).forEach(([m,v])=>{s.stock[m]=(s.stock[m]||0)+v});delete s.spent[t.n]}
  /* other upgrades you are on right now that need the same item (the count is shared, so it can only be spent once) */
  function sharedWith(L,m){return LINES.filter(o=>o!==L&&o.tiers[done(o)]&&reqs(o.tiers[done(o)]).some(r=>r.m===m)).map(lineName)}
  const reqs=t=>{const r=[];if(t.cash)r.push({m:'DMZ Cash',need:t.cash,cash:true});t.c.forEach(([n,q])=>r.push({m:n,need:q}));return r};
  const lineName=L=>L.key.replace(/ Upgrade$/,'');
  function totals(){const need={};LINES.forEach(L=>{const d=done(L);if(d>=L.tiers.length)return;reqs(L.tiers[d]).forEach(r=>{need[r.m]=(need[r.m]||0)+r.need})});const out={cash:0,items:{}};Object.entries(need).forEach(([m,q])=>{const left=Math.max(0,q-haveOf(null,m));if(m==='DMZ Cash')out.cash=left;else if(left)out.items[m]=left});return out}
  /* hover (or tap) an item in "Still to collect" to see where to get it */
  const CASH_TIP='<b>DMZ Cash</b>There is no single place to find it. Dynamic Ops pay 10,000 to 20,000, Side Ops 2,000 and each Mission Step 500.';
  function chipTip(n){
    if(n==='DMZ Cash')return {html:CASH_TIP,id:null};
    const i=window.itemInfo?itemInfo(n):null;
    const w=i&&i.where.length?i.where.slice(0,2).map(esc).join('<br>'):'Where to find it is not known yet.';
    return {html:`<b>${esc(n)}</b>${w}${i&&i.hasMap?'<br><i>Marked on the map.</i>':''}${i?'<br><em class="tip-hint">Click for the full details</em>':''}`,id:i?i.id:null};
  }
  function bindChips(){
    const canHover=window.matchMedia&&matchMedia('(hover:hover)').matches;
    document.querySelectorAll('#upNeed .up-chip').forEach(c=>{
      const n=c.dataset.n,show=()=>{const t=chipTip(n);chipTipOn=true;showTip(c,t.html,c.classList.contains('cash')?'var(--gold)':undefined)};
      if(canHover){c.onmouseenter=show;c.onmouseleave=hideTip}
      c.onfocus=show;c.onblur=hideTip;
      c.onclick=()=>{const t=chipTip(n);
        if(!t.id){show();return}
        if(canHover||c.dataset.armed==='1'){hideTip();openView('items/'+t.id);return}
        document.querySelectorAll('#upNeed .up-chip').forEach(x=>x.dataset.armed='');c.dataset.armed='1';show();
      };
    });
  }
  let chipTipOn=false;   // only close a tip this tracker opened, never one belonging to another page
  document.addEventListener('pointerdown',e=>{if(chipTipOn&&!e.target.closest('#upNeed .up-chip')){chipTipOn=false;hideTip();document.querySelectorAll('#upNeed .up-chip').forEach(x=>x.dataset.armed='')}});
  function paintTotals(){
    const t=totals(),items=Object.entries(t.items).filter(e=>e[1]>0).sort((a,b)=>b[1]-a[1]);
    const total=UPG.length,dn=LINES.reduce((s,L)=>s+done(L),0);
    $('upDone').textContent=dn+' / '+total;$('upBar').style.width=(100*dn/total)+'%';$('upStat').textContent=dn;if($('upPct'))$('upPct').textContent=Math.round(100*dn/total)+'%';paintLines();
    $('upNeed').innerHTML=(items.length||t.cash)?`<div class="up-need-list">${t.cash?`<button type="button" class="up-chip cash" data-n="DMZ Cash"><b>$${nfmt(t.cash)}</b> DMZ Cash</button>`:''}${items.map(([n,q])=>`<button type="button" class="up-chip" data-n="${esc(n)}"><img src="${ingIcon(n)}" alt=""><b>${nfmt(q)}</b> ${esc(n)}</button>`).join('')}</div>`:'<p class="up-empty">Everything for your current upgrades is collected.</p>';bindChips()}
  function paintCard(L,card){
    const d=done(L),t=L.tiers[d];if(!t)return;const rs=reqs(t);let ready=0;
    rs.forEach((r,i)=>{const h=haveOf(t,r.m),ok=h>=r.need;if(ok)ready++;const row=card.querySelector(`[data-r="${i}"]`);if(!row)return;row.classList.toggle('ok',ok);row.querySelector('.up-bar i').style.width=Math.min(100,100*h/Math.max(1,r.need))+'%'});
    const s=card.querySelector('.up-ready');if(s)s.textContent=rs.length?ready+' of '+rs.length+' ready':'Nothing to collect';
    const b=card.querySelector('.up-go');if(b){const all=ready===rs.length;b.classList.toggle('ready',all);b.textContent=all?'Mark complete':'Mark complete anyway'}
  }
  function cardHTML(L,i){
    const d=done(L),n=L.tiers.length;
    const chips=n>1?`<div class="up-chips">${L.tiers.slice(0,d).map((t,k)=>`<button type="button" class="up-done" data-back="${k}" title="Undo back to ${esc(t.n)}">✓ ${esc(t.n.replace(L.key+' ',''))||'Done'}</button>`).join('')}</div>`:'';
    if(d>=n)return `<article class="up-card complete" data-l="${i}"><div class="up-head"><span class="up-ic">${L.tiers[0].p?`<img src="${L.tiers[0].p}" alt="">`:''}</span><div><h3>${esc(lineName(L))}</h3><span class="up-tier">All ${n} ${n>1?'tiers':'tier'} complete</span></div></div>${chips}<p class="up-all">Nothing left to collect for this upgrade.</p><button type="button" class="up-undo" data-back="${n-1}">Undo last tier</button></article>`;
    const t=L.tiers[d],rs=reqs(t);
    return `<article class="up-card" data-l="${i}"><div class="up-head"><span class="up-ic">${t.p?`<img src="${t.p}" alt="">`:''}</span><div><h3>${esc(lineName(L))}</h3><span class="up-tier">${n>1?'Tier '+(d+1)+' of '+n+' // ':''}${esc(t.n)}</span></div></div>
      ${t.d?`<p class="up-eff">${esc(t.d)}</p>`:''}${chips}
      <div class="up-reqs">${rs.map((r,k)=>{const step=r.cash?(r.need>=100000?10000:1000):1;return `<div class="up-req" data-r="${k}"><div class="up-rn">${r.cash?'<span class="up-cash-ic">$</span>':`<img src="${ingIcon(r.m)}" alt="">`}<span>${esc(r.m)}</span><em>need ${nfmt(r.need)}</em></div>${(()=>{const o=r.cash?[]:sharedWith(L,r.m);return o.length?`<p class="up-share">Same count as ${esc(o.join(', '))}</p>`:''})()}<div class="up-ctl"><button type="button" class="up-step" data-d="-${step}" aria-label="Less ${esc(r.m)}">−</button><input type="text" inputmode="numeric" value="${nfmt(haveOf(t,r.m))}" aria-label="${esc(r.m)} you have" data-m="${esc(r.m)}"><button type="button" class="up-step" data-d="${step}" aria-label="More ${esc(r.m)}">+</button></div><div class="up-bar"><i></i></div></div>`}).join('')}${t.cu?'<p class="up-unk">Cash cost not known yet.</p>':''}${rs.length?'':'<p class="up-unk">No materials listed.</p>'}</div>
      <div class="up-foot"><span class="up-ready"></span><button type="button" class="up-go">Mark complete</button></div></article>`}
  /* the list of upgrade lines on the left; the selected one shows in full on the right */
  let sel=-1;
  const CHEV='<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 5l7 7-7 7"/></svg>';
  function paintLines(){
    const box=$('upLines');if(!box)return;
    box.innerHTML=LINES.map((L,i)=>{const d=done(L),n=L.tiers.length,t=L.tiers[Math.min(d,n-1)],all=d>=n;
      return `<button type="button" class="up-line${i===sel?' sel':''}${all?' complete':''}" data-l="${i}" role="listitem" aria-current="${i===sel}"><span class="ul-ic">${L.tiers[0].p?`<img src="${L.tiers[0].p}" alt="">`:''}</span><span class="ul-t"><b>${esc(lineName(L))}</b><small>${esc((L.tiers[0].d||'').split('. ')[0].replace(/\.$/,''))}</small></span><span class="ul-tier">${all?'Done':'Tier '+(d+1)+' / '+n}</span><span class="ul-p"><span class="ul-pl"><span>${all?'All tiers complete':esc(t.n)}</span><span>${d} / ${n} done</span></span><span class="trk-bar sm"><i style="width:${100*d/n}%"></i></span></span>${CHEV}</button>`}).join('');
    box.querySelectorAll('.up-line').forEach(b=>b.onclick=()=>{sel=+b.dataset.l;showSel(true)});
  }
  function showSel(scroll){
    document.querySelectorAll('#upGrid .up-card').forEach(c=>c.classList.toggle('sel',+c.dataset.l===sel));
    document.querySelectorAll('#upLines .up-line').forEach(b=>{const on=+b.dataset.l===sel;b.classList.toggle('sel',on);b.setAttribute('aria-current',on)});
    if(scroll&&matchMedia('(max-width:980px)').matches){const c=document.querySelector('#upGrid .up-card.sel');if(c)c.scrollIntoView({behavior:'smooth',block:'start'})}
  }
  function render(){
    if(sel<0){sel=LINES.findIndex(L=>done(L)<L.tiers.length);if(sel<0)sel=0}
    const g=$('upGrid');g.innerHTML=LINES.map(cardHTML.bind(null)).join('');
    g.querySelectorAll('.up-card').forEach(card=>{const L=LINES[+card.dataset.l];
      card.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{const to=+b.dataset.back,s=st();for(let k=done(L)-1;k>=to;k--)refund(L.tiers[k]);s.done=s.done||{};s.done[L.key]=to;Store.save();render();toast('Back to '+L.tiers[to].n+'. Its items are back in your counts.')});
      const go=card.querySelector('.up-go');if(go)go.onclick=()=>{const d=done(L),s=st();spend(L.tiers[d]);s.done=s.done||{};s.done[L.key]=d+1;Store.save();const nx=L.tiers[d+1];render();toast(nx?L.tiers[d].n+' complete. Next: '+nx.n:L.tiers[d].n+' complete. All tiers done.')};
      const d=done(L),t=L.tiers[d];if(!t)return;const rs=reqs(t);
      card.querySelectorAll('.up-req').forEach(row=>{const r=rs[+row.dataset.r],inp=row.querySelector('input');
        const apply=v=>{setHave(t,r.m,v);inp.value=nfmt(haveOf(t,r.m));paintCard(L,card);paintTotals()};
        row.querySelectorAll('.up-step').forEach(b=>b.onclick=()=>apply(haveOf(t,r.m)+ +b.dataset.d));
        inp.onfocus=()=>{inp.value=String(haveOf(t,r.m));inp.select()};inp.onblur=()=>{inp.value=nfmt(haveOf(t,r.m))};
        inp.oninput=()=>{const v=parseInt(inp.value.replace(/[^0-9]/g,''),10)||0;setHave(t,r.m,v);paintCard(L,card);paintTotals()};
        inp.onkeydown=e=>{if(e.key==='Enter')inp.blur();if(e.key==='ArrowUp'){e.preventDefault();apply(haveOf(t,r.m)+(r.cash?1000:1))}if(e.key==='ArrowDown'){e.preventDefault();apply(haveOf(t,r.m)-(r.cash?1000:1))}}});
      paintCard(L,card)});
    paintTotals();showSel(false);
  }
  window.upRender=()=>render();
  inits.upgrades=function(){
    migrate();Account.paintNotes();
    $('upReset').onclick=()=>{if(confirm(Account.user?'Clear all of your upgrade progress? It will also be cleared from your account.':'Clear all of your upgrade progress in this browser?')){const keep=Store.get('upgrades').stock;Store.data.upgrades={};if(keep)Store.data.upgrades.stock=keep;Store.save();render()}};
    render();
  };
  window.upShow=function(){if($('upGrid').children.length){migrate();render()}};
})();

/* ===== CAMO TRACKER ===== */
(function(){
  const CATS=[...new Set(CAMO_WEAPONS.map(w=>w.cat))];
  const TN={M:'Military',S:'Special',C:'Completionist',P:'Prestige',X:'Mastery'};
  const st=()=>Store.get('camos');
  const wd=id=>((st().w||{})[id])||{};
  const isDone=(id,i)=>!!wd(id)[i];
  const setDone=(id,i,v)=>{const s=st();s.w=s.w||{};const o=s.w[id]=s.w[id]||{};if(v)o[i]=1;else delete o[i];Store.save()};
  const gDone=i=>!!((st().g||{})[i]);
  const setG=(i,v)=>{const s=st();s.g=s.g||{};if(v)s.g[i]=1;else delete s.g[i];Store.save()};
  const cnt=W=>W.c.reduce((n,_,i)=>n+(isDone(W.id,i)?1:0),0);
  const lvlOf=id=>((st().lvl||{})[id])||0;
  const req=c=>/not (extracted|fully shown)/i.test(c[2])?'Challenge not known yet':c[2].replace(/\.$/,'');
  const sw=(c,i)=>c[3]?`<img class="cm-sw" src="${c[3]}" alt="">`:`<span class="cm-sw mil">${c[0]==='M'?(c[4]?c[4]:i+1):''}</span>`;
  let filter='All',query='',open=null,tab='M',selI=-1;
  const gimg=W=>(GUNS[W.id]||{}).img||'';
  function totals(){let d=0,t=0;CAMO_WEAPONS.forEach(W=>{d+=cnt(W);t+=W.c.length});CAMO_GLOBAL.forEach((_,i)=>{t++;if(gDone(i))d++});return [d,t]}
  function paintTop(){const [d,t]=totals();$('cmDone').textContent=d+' / '+t;$('cmPct').textContent='('+Math.round(100*d/t)+'%)';$('cmBar').style.width=(100*d/t)+'%';$('cmStat').textContent=d;if(window.tileProgress)tileProgress()}
  const list=()=>{const q=query.trim().toLowerCase();return CAMO_WEAPONS.filter(W=>(filter==='All'||W.cat===filter)&&(!q||W.n.toLowerCase().includes(q)))};
  function renderCats(){
    const chips=['All',...CATS];
    $('cmChips').innerHTML=chips.map(c=>{const n=c==='All'?CAMO_WEAPONS.length:CAMO_WEAPONS.filter(W=>W.cat===c).length;return `<button type="button" class="cm-cat${c===filter?' on':''}" data-c="${esc(c)}" aria-pressed="${c===filter}"><span>${esc(c==='All'?'All weapons':c)}</span><b>${n}</b></button>`}).join('');
    $('cmChips').querySelectorAll('.cm-cat').forEach(b=>b.onclick=()=>{filter=b.dataset.c;renderCats();renderGrid()});
  }
  function renderGrid(){
    const L=list();$('cmListH').textContent=(filter==='All'?'All weapons':filter)+' ('+L.length+')';
    $('cmGrid').innerHTML=L.length?L.map(W=>{const d=cnt(W),n=W.c.length;return `<button type="button" class="cm-wi${W.id===open?' on':''}" data-w="${W.id}" role="option" aria-selected="${W.id===open}"><span class="cm-wpic">${gimg(W)?`<img src="${gimg(W)}" alt="" loading="lazy">`:''}</span><span class="cm-wn">${esc(W.n)}</span><span class="cm-wc${d===n?' all':''}">${d}/${n}</span></button>`}).join(''):'<p class="up-empty">No weapons match that search.</p>';
    $('cmGrid').querySelectorAll('.cm-wi').forEach(b=>b.onclick=()=>openW(b.dataset.w,true));
  }
  function openW(id,scroll){
    if(open!==id){open=id;tab='M';selI=-1}
    $('cmGrid').querySelectorAll('.cm-wi').forEach(b=>{const on=b.dataset.w===id;b.classList.toggle('on',on);b.setAttribute('aria-selected',on)});
    renderDetail();
    if(scroll&&matchMedia('(max-width:980px)').matches)$('cmDetail').scrollIntoView({behavior:'smooth',block:'start'});
  }
  function renderDetail(){
    const W=CAMO_WEAPONS.find(x=>x.id===open);if(!W){$('cmDetail').innerHTML='';return}
    const types=['M','S','C','P'].filter(k=>W.c.some(c=>c[0]===k));if(!types.includes(tab))tab=types[0];
    const idx=W.c.map((c,i)=>c[0]===tab?i:-1).filter(i=>i>=0);
    if(!idx.includes(selI))selI=idx.find(i=>!isDone(W.id,i));if(selI===undefined)selI=idx[0];
    const d=cnt(W),n=W.c.length,c=W.c[selI],on=isDone(W.id,selI);
    $('cmDetail').innerHTML=`<div class="cmd-h"><div class="cmd-t"><b>${esc(W.n)}</b><small>${esc(W.cat)}</small></div><span class="cmd-pic">${gimg(W)?`<img src="${gimg(W)}" alt="">`:''}</span>
      <div class="cmd-lvl"><span>Weapon level</span><div class="cmd-step"><button type="button" data-lv="-1" aria-label="Lower weapon level">−</button><input type="text" inputmode="numeric" id="cmLvl" value="${lvlOf(W.id)||0}" aria-label="My weapon level"><button type="button" data-lv="1" aria-label="Raise weapon level">+</button></div><small>Military camos up to this level tick themselves.</small></div>
      <div class="cmd-comp"><span>Camo completion (${esc(W.n)})</span><div class="cmd-cb"><div class="trk-bar"><i style="width:${100*d/n}%"></i></div><b>${d} / ${n} (${Math.round(100*d/n)}%)</b></div></div></div>
      <div class="cmd-tabs" role="tablist">${types.map(k=>{const ii=W.c.map((c,i)=>c[0]===k?i:-1).filter(i=>i>=0);return `<button type="button" role="tab" class="cmd-tab${k===tab?' on':''}" data-t="${k}" aria-selected="${k===tab}">${TN[k]} (${ii.filter(i=>isDone(W.id,i)).length}/${ii.length})</button>`}).join('')}</div>
      <div class="cmd-body"><div class="cmd-sw">${idx.map(i=>{const cc=W.c[i],dn=isDone(W.id,i);return `<button type="button" class="cm-tile${dn?' done':''}${i===selI?' sel':''}" data-i="${i}" aria-pressed="${i===selI}"><span class="cmt-sw">${sw(cc,i)}</span><span class="cmt-n">${esc(cc[1].replace(/^Military camo /,'Military '))}</span>${dn?'<span class="cmt-ok" aria-label="done">✓</span>':''}</button>`}).join('')}</div>
      <div class="cmd-info"><div class="cmi-h"><span class="cmi-sw">${sw(c,selI)}</span><div><b>${esc(c[1])}</b><small>${TN[c[0]]} camo</small></div>${on?'<span class="cmi-st ok">✓ Completed</span>':'<span class="cmi-st">Not done</span>'}</div>
        <div class="cmi-ch"><h3>Challenge</h3><p>${esc(req(c))}${c[0]==='M'&&c[4]&&!/level/i.test(req(c))?' (weapon level '+c[4]+')':''}.</p></div>
        <button type="button" class="cmi-go${on?' undo':''}" id="cmDoneBtn">${on?'Undo':'✓ Done'}</button></div></div>
      <div class="cmd-f"><button type="button" class="up-undo" id="cmWReset">Reset this weapon</button></div>`;
    const D=$('cmDetail');
    D.querySelectorAll('.cmd-tab').forEach(b=>b.onclick=()=>{tab=b.dataset.t;selI=-1;renderDetail()});
    D.querySelectorAll('.cm-tile').forEach(b=>b.onclick=()=>{selI=+b.dataset.i;renderDetail()});
    $('cmDoneBtn').onclick=()=>{const v=!isDone(W.id,selI);setDone(W.id,selI,v);if(v)toast(W.c[selI][1]+' done');refresh()};
    const lv=$('cmLvl'),setLv=v=>{v=Math.max(0,Math.min(250,v));const s=st();s.lvl=s.lvl||{};s.lvl[W.id]=v;Store.save();W.c.forEach((cc,i)=>{if(cc[0]==='M'&&cc[4]&&cc[4]<=v)setDone(W.id,i,true)})};
    lv.onchange=()=>{setLv(parseInt(lv.value.replace(/[^0-9]/g,''),10)||0);refresh()};lv.onkeydown=e=>{if(e.key==='Enter')lv.blur()};
    lv.onfocus=()=>lv.select();
    D.querySelectorAll('[data-lv]').forEach(b=>b.onclick=()=>{setLv(lvlOf(W.id)+ +b.dataset.lv);refresh()});
    $('cmWReset').onclick=()=>{if(confirm('Clear all '+W.n+' camos?')){const s=st();s.w=s.w||{};delete s.w[W.id];if(s.lvl)delete s.lvl[W.id];Store.save();refresh()}};
  }
  function refresh(){renderGrid();renderDetail();paintTop()}
  function renderGlobal(){
    $('cmGlobal').innerHTML=CAMO_GLOBAL.map((c,i)=>{const on=gDone(i);return `<button type="button" class="cm-row${on?' on':''}" data-g="${i}" role="checkbox" aria-checked="${on}"><span class="cm-tick">${on?'✓':''}</span>${sw(c,i)}<span class="cm-rt"><b>${esc(c[1])}</b><small>${esc(c[0]==='X'?'Mastery // ':'')}${esc(req(c))}</small></span></button>`}).join('');
    $('cmGlobal').querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{const i=+b.dataset.g,v=!gDone(i);setG(i,v);b.classList.toggle('on',v);b.setAttribute('aria-checked',v);b.querySelector('.cm-tick').textContent=v?'✓':'';paintTop()});
  }
  window.cmRender=()=>{renderCats();renderGrid();renderDetail();renderGlobal();paintTop()};
  inits.camos=function(){
    Account.paintNotes();
    $('cmSearch').oninput=e=>{query=e.target.value;renderGrid()};
    $('cmReset').onclick=()=>{if(confirm(Account.user?'Clear all of your camo progress? It will also be cleared from your account.':'Clear all of your camo progress in this browser?')){Store.get('camos');Store.data.camos={};Store.save();renderGrid();renderDetail();renderGlobal();paintTop()}};
    open=CAMO_WEAPONS[0].id;renderCats();renderGrid();renderDetail();renderGlobal();paintTop();
  };
  window.camoClose=function(){};
  window.camoShow=function(){if($('cmGrid').children.length){renderGrid();renderDetail();paintTop()}};
})();

/* ===== DMZ PATCH NOTES (data comes from /api/dmz-patches/*, filled by the scheduled checker) ===== */
(function(){
  const API='/api/dmz-patches';
  const D=(iso,tz)=>{const t=Date.parse(iso);return Number.isNaN(t)?'':new Date(t).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:tz||'UTC'})};
  const DT=iso=>{const t=Date.parse(iso);return Number.isNaN(t)?'':new Date(t).toLocaleString('en-AU',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',timeZone:'Australia/Melbourne',timeZoneName:'short'})};
  const BADGE={NEW:'new',UPDATED:'upd',RESOLVED:'res'};
  const get=async(path)=>{const c=new AbortController();const t=setTimeout(()=>c.abort(),12000);try{const r=await fetch(API+path,{signal:c.signal,headers:{accept:'application/json'}});if(r.status===503)return {notConfigured:true};if(!r.ok)throw new Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(t)}};
  const when=e=>e.published_at?'Published '+D(e.published_at):(e.first_detected_at?'Detected '+D(e.first_detected_at,'Australia/Melbourne'):'');
  const badge=e=>e.status?`<span class="pn-badge ${BADGE[e.status]||''}">${esc(e.status)}</span>`:'';

  /* ---- home strip: top three updates ---- */
  async function loadStrip(){
    const box=document.getElementById('latestUpdate');if(!box)return;
    // loading placeholder while the updates arrive
    box.hidden=false;box.classList.add('is-loading');document.getElementById('latestList').innerHTML=Array.from({length:3},()=>'<li class="sk-item" aria-hidden="true"><span class="sk sk-badge"></span><span class="sk sk-line"></span><span class="sk sk-line short"></span></li>').join('');
    try{
      const d=await get('/latest?n=3');
      box.classList.remove('is-loading');
      if(!d||d.notConfigured||!d.items||!d.items.length){box.hidden=true;return}
      const kind=e=>/resol|fixed/i.test(e.category||'')?'lt-ok':/investig|known|monitor/i.test(e.category||'')?'lt-watch':'lt-other';
      const shortDate=e=>e.published_at?D(e.published_at):(e.first_detected_at?D(e.first_detected_at,'Australia/Melbourne'):'');
      document.getElementById('latestList').innerHTML=d.items.slice(0,3).map(e=>`<li><button type="button" class="latest-item" data-id="${esc(e.id)}"><span class="latest-top"><span class="lt-badge ${kind(e)}">${esc(e.category)}</span>${e.status?`<span class="lt-new">${esc(e.status)}</span>`:''}</span><span class="latest-date">${esc(shortDate(e))}</span><span class="latest-title">${esc(e.title)}</span><span class="latest-sum">${esc(e.summary)}</span><span class="latest-read">Read update <span aria-hidden="true">&rarr;</span></span></button></li>`).join('');
      document.getElementById('latestMeta').textContent=d.last_success?'Last checked '+DT(d.last_success):'';
      document.querySelectorAll('#latestList .latest-item').forEach(b=>b.onclick=()=>{try{sessionStorage.setItem('pnFocus',b.dataset.id)}catch(e){}openView('patches')});
      box.hidden=false;
    }catch(e){box.classList.remove('is-loading');box.hidden=true}
  }

  /* ---- full page ---- */
  const S={q:'',cat:'',page:1,pages:1,items:[],cats:[],loading:false,err:null,none:false};
  const list=()=>document.getElementById('pnList');
  const cardHTML=e=>{
    const revs=(e.revisions&&e.revisions[0])?`<span class="pn-rev">Revision ${e.revision}: ${e.revisions[0].added} added, ${e.revisions[0].removed} removed</span>`:(e.revision>1?`<span class="pn-rev">Revision ${e.revision}</span>`:'');
    return `<article class="pn-card" data-id="${esc(e.id)}"><div class="pn-top">${badge(e)}<span class="pn-cat">${esc(e.category)}</span><span class="pn-date">${esc(when(e))}</span>${revs}</div>
      <h3>${esc(e.title)}</h3><p class="pn-sum">${esc(e.summary)}</p>
      <div class="pn-actions"><button type="button" class="pn-more" aria-expanded="false">Show ${e.details.length} ${e.details.length===1?'change':'changes'}</button>${e.source_url?`<a class="pn-src" href="${esc(e.source_url)}" target="_blank" rel="noopener">${esc(e.source_name||'Official source')} &#8599;</a>`:''}</div>
      <ul class="pn-det" hidden>${e.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></article>`};
  function paint(){
    const L=list();if(!L)return;
    document.getElementById('pnState').textContent=S.loading&&!S.items.length?'Loading patch notes...':'';
    document.getElementById('pnError').hidden=!S.err;document.getElementById('pnEmpty').hidden=!(S.none&&!S.loading&&!S.err);
    document.getElementById('pnEmpty').textContent=S.none==='setup'?'Issue tracking is being set up. Official DMZ updates will appear here soon.':(S.q||S.cat?'No updates match that search.':'No DMZ issues or fixes have been listed yet. Check back soon.');
    L.innerHTML=S.items.map(cardHTML).join('');
    L.querySelectorAll('.pn-card').forEach(c=>{const b=c.querySelector('.pn-more'),u=c.querySelector('.pn-det');b.onclick=()=>{const open=u.hidden;u.hidden=!open;b.setAttribute('aria-expanded',open);b.textContent=open?'Hide changes':'Show '+u.children.length+(u.children.length===1?' change':' changes')}});
    document.getElementById('pnMore').hidden=!(S.page<S.pages);
    const cs=document.getElementById('pnChips');
    if(S.cats.length){cs.innerHTML=['All',...S.cats].map(c=>`<button type="button" class="lt-chip${(c==='All'?'':c)===S.cat?' on':''}" data-c="${esc(c==='All'?'':c)}">${esc(c)}</button>`).join('');cs.querySelectorAll('.lt-chip').forEach(b=>b.onclick=()=>{S.cat=b.dataset.c;load(true)})}
  }
  async function load(reset){
    if(S.loading)return;S.loading=true;S.err=null;if(reset){S.page=1;S.items=[]}paint();
    try{
      const qs=new URLSearchParams({page:S.page,per:10});if(S.q)qs.set('q',S.q);if(S.cat)qs.set('cat',S.cat);
      const d=await get('/history?'+qs);
      if(d.notConfigured){S.none='setup';S.items=[]}
      else{S.items=S.items.concat(d.items);S.pages=d.pages;if(d.categories&&d.categories.length&&!S.cats.length)S.cats=d.categories;S.none=S.items.length?false:true}
    }catch(e){S.err=true}
    S.loading=false;paint();focusEntry();
  }
  function focusEntry(){
    let id=null;try{id=sessionStorage.getItem('pnFocus');if(id)sessionStorage.removeItem('pnFocus')}catch(e){}
    if(!id)return;const c=[...document.querySelectorAll('#pnList .pn-card')].find(x=>x.dataset.id===id);
    if(c){c.classList.add('hit');c.querySelector('.pn-more').click();c.scrollIntoView({block:'center'})}
  }
  async function loadStatus(){
    try{
      const s=await get('/status');const el=document.getElementById('pnChecked');
      if(s.notConfigured){el.textContent='';return}
      const bad=(s.sources||[]).filter(x=>x.ok===false);
      el.textContent=(s.last_success?'Last checked '+DT(s.last_success)+'. ':'Not checked yet. ')+'The official issue tracker is checked 4 times a day.'+(bad.length?' Some sources could not be reached at the last check; the most recent confirmed information is shown.':'');
    }catch(e){}
  }
  inits.patches=function(){
    let t;document.getElementById('pnSearch').oninput=e=>{clearTimeout(t);t=setTimeout(()=>{S.q=e.target.value.trim();load(true)},300)};
    document.getElementById('pnMore').onclick=()=>{S.page++;load(false)};
    document.getElementById('pnRetry').onclick=()=>load(true);
    load(true);loadStatus();
  };
  window.patchShow=function(){if(S.items.length||S.none)focusEntry()};
  loadStrip();
})();

/* ===== ITEM SEARCH: materials, gear, keys and upgrades in one place ===== */
(function(){
  const norm=s=>String(s).toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g,' ').replace(/\s+/g,' ').trim();
  const slug=s=>norm(s).replace(/ /g,'-');
  const GENERIC_WHERE=/^found while looting\.? no fixed location\.?$/i;
  const KEY_SVG='<svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="10" cy="16" r="6" fill="none" stroke="currentColor" stroke-width="2.6"/><path d="M16 16h13M24 16v6M29 16v4" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg>';
  const TYPE_ORDER={Material:0,Gear:1,Key:2,Upgrade:3};
  let ITEMS=null,BY=null;

  /* ---------- build the list once ---------- */
  function build(){
    if(ITEMS)return;
    const items=[],mats=new Map();
    const UPG=GEAR_DATA.find(g=>g.c==='Upgrades').r,ING=GEAR_DATA.find(g=>g.c==='Ingredients').r;
    const recipes=[];GEAR_DATA.forEach(g=>{if(g.c==='Upgrades'||g.c==='Ingredients')return;g.r.forEach(it=>recipes.push({it,cat:g.c}))});
    const M=n=>{if(!mats.has(n))mats.set(n,{name:n,usedBy:[],upgrades:[],craft:null,map:null});return mats.get(n)};
    recipes.forEach(({it,cat})=>it.c.forEach(([n,q])=>M(n).usedBy.push({it,cat,q})));
    ING.forEach(it=>{M(it.n).craft=it;it.c.forEach(([n,q])=>M(n).usedBy.push({it,cat:'Ingredients',q}))});
    // upgrade lines (same grouping as the Upgrades tracker)
    const romans=/ ([IVX]+)$/,lines=[];
    UPG.forEach(t=>{const key=t.n.replace(romans,'');let L=lines.find(l=>l.key===key);if(!L){L={key,tiers:[]};lines.push(L)}L.tiers.push(t)});
    lines.forEach(L=>L.tiers.forEach((t,k)=>t.c.forEach(([n,q])=>M(n).upgrades.push({t,q,line:L,k}))));
    MAP_ING.forEach(g=>{M(g.n).map=g});
    mats.forEach(m=>items.push({id:'m-'+slug(m.name),type:'Material',name:m.name,icon:ingIcon(m.name),sub:m.craft&&m.craft.r?m.craft.r:'Material',alias:'ingredient material resource',mat:m}));
    recipes.forEach(({it,cat})=>items.push({id:'g-'+slug(it.n),type:'Gear',name:it.n,icon:it.p||(it.ic&&ING_ICON[it.ic])||ING_GENERIC,sub:cat+(it.r?' · '+it.r:''),alias:cat+' recipe craft printer '+(it.r||''),it,cat}));
    const seenKey=new Set();
    MAP_KEYS.entries.forEach(e=>{const id='k-'+slug(e.n);if(seenKey.has(id)){const o=items.find(x=>x.id===id);if(o&&e.h&&!(o.entries[0].h||'').includes(e.h))o.entries.push(e);return}seenKey.add(id);items.push({id,type:'Key',name:e.n,icon:null,sub:'Locked door key'+(e.r?' · '+e.r:''),alias:'key door locked '+(e.a2||'')+' '+(e.alias||''),entries:[e]})});
    lines.forEach(L=>{items.push({id:'u-'+slug(L.key),type:'Upgrade',name:L.key,icon:L.tiers[0].p||ING_GENERIC,sub:L.tiers.length>1?L.tiers.length+' tiers':'1 tier',alias:'upgrade fob station',line:L,isLine:true});
      L.tiers.forEach((t,k)=>items.push({id:'t-'+slug(t.n),type:'Upgrade',name:t.n,icon:t.p||ING_GENERIC,sub:'Upgrade tier',alias:'upgrade tier',line:L,tier:t,k,hidden:L.tiers.length===1}))});
    ITEMS=items.filter(x=>!x.hidden);BY=new Map(items.map(x=>[x.id,x]));
    ITEMS.forEach(x=>{x.n=norm(x.name);x.t=x.n.split(' ');x.hay=norm(x.name+' '+(x.alias||''))});
  }

  /* ---------- search ---------- */
  function search(q,max=8){
    build();const nq=norm(q);if(!nq)return[];const qt=nq.split(' ');const out=[];
    ITEMS.forEach(x=>{
      let s=0;
      if(x.n===nq)s=100;else if(x.n.startsWith(nq))s=80;
      else if(qt.every(t=>x.t.some(w=>w.startsWith(t))))s=60;
      else if(nq.length>=4&&x.n.includes(nq))s=45;
      else if(qt.every(t=>x.hay.includes(t))&&nq.length>=3)s=20;
      if(s){if(x.isLine)s+=2;out.push([s-TYPE_ORDER[x.type]*0.5-x.n.length*0.01,x])}
    });
    return out.sort((a,b)=>b[0]-a[0]).slice(0,max).map(a=>a[1]);
  }

  /* ---------- drop-down used on the home page and on the Items page ---------- */
  function mount(input,list,onPick,find=search){
    let hits=[],cur=-1;
    const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');cur=-1;input.removeAttribute('aria-activedescendant')};
    const paint=()=>{
      list.innerHTML=hits.length?hits.map((x,i)=>`<li role="option" id="${list.id}-${i}" data-i="${i}" class="${i===cur?'on':''}" aria-selected="${i===cur}">${x.svg?`<span class="is-sv">${x.svg}</span>`:x.icon?`<img src="${x.icon}" alt="">`:`<span class="is-key">${KEY_SVG}</span>`}<span class="is-nm">${esc(x.name)}</span><span class="is-tp t-${x.type.toLowerCase()}">${esc(x.type)}</span></li>`).join(''):`<li class="is-none" role="option" aria-disabled="true">No match. Try another name.</li>`;
      list.hidden=false;input.setAttribute('aria-expanded','true');
      list.querySelectorAll('li[data-i]').forEach(li=>{li.onmousedown=e=>{e.preventDefault();pick(+li.dataset.i)};li.onmousemove=()=>{if(cur!==+li.dataset.i){cur=+li.dataset.i;mark()}}});
    };
    const mark=()=>{list.querySelectorAll('li[data-i]').forEach((li,i)=>{li.classList.toggle('on',i===cur);li.setAttribute('aria-selected',i===cur)});if(cur>=0){input.setAttribute('aria-activedescendant',list.id+'-'+cur);const el=list.children[cur];if(el&&el.scrollIntoView)el.scrollIntoView({block:'nearest'})}};
    const pick=i=>{const x=hits[i];if(!x)return;input.value=x.name;close();onPick(x)};
    input.addEventListener('input',()=>{const q=input.value;if(!q.trim()){hits=[];close();return}hits=find(q);cur=hits.length?0:-1;paint()});
    input.addEventListener('focus',()=>{if(input.value.trim()){hits=find(input.value);cur=hits.length?0:-1;paint()}});
    input.addEventListener('keydown',e=>{
      if(e.key==='ArrowDown'){e.preventDefault();if(list.hidden&&input.value.trim()){hits=search(input.value);cur=0;paint()}else if(hits.length){cur=(cur+1)%hits.length;mark()}}
      else if(e.key==='ArrowUp'){e.preventDefault();if(hits.length){cur=(cur-1+hits.length)%hits.length;mark()}}
      else if(e.key==='Enter'){if(!list.hidden&&cur>=0){e.preventDefault();pick(cur)}else if(input.value.trim()){const h=search(input.value);if(h.length){e.preventDefault();input.value=h[0].name;close();onPick(h[0])}}}
      else if(e.key==='Escape'){if(!list.hidden){e.stopPropagation();close()}}
    });
    input.addEventListener('blur',()=>setTimeout(close,120));
    return {close};
  }

  /* ---------- helpers for the detail pages ---------- */
  const num=n=>(+n).toLocaleString('en-AU');
  const link=x=>`<button type="button" class="it-link" data-go="${esc(x.id)}">${x.icon?`<img src="${x.icon}" alt="">`:''}<span>${esc(x.name)}</span></button>`;
  const matItem=name=>BY.get('m-'+slug(name));
  const matLink=(name,q)=>{const x=matItem(name);return `<span class="it-row">${x?link(x):`<span>${esc(name)}</span>`}${q!=null?`<b class="it-q">×${num(q)}</b>`:''}</span>`};
  const sec=(h,body)=>body?`<section class="it-sec"><h2>${h}</h2>${body}</section>`:'';
  const para=t=>`<p>${esc(t)}</p>`;
  const bullets=a=>a.length?`<ul class="it-ul">${a.map(t=>`<li>${t}</li>`).join('')}</ul>`:'';
  const missing=a=>a.length?`<div class="it-missing"><b>Not known yet:</b> ${a.map(esc).join(' · ')}</div>`:'';
  const upgDone=line=>{try{return Math.min(((Store.get('upgrades').done||{})[line.key])||0,line.tiers.length)}catch(e){return 0}};

  function whereMention(name){
    const out=[],n=norm(name),nn=n.replace(/s$/,'');
    BOSS_STRATS.forEach(b=>{const r=norm(b.rewards||'');if(r&&(r.includes(n)||r.includes(nn)))out.push(`Possible reward from <button type="button" class="it-link text" data-boss="${esc(b.id)}">${esc(b.name)}</button> (${esc(b.location||'')})`)});
    LOOT_SPOTS.forEach(s=>{const hay=norm([s.name,s.summary,s.intro,(s.steps||[]).map(x=>x.h+' '+x.p).join(' ')].join(' '));if(hay.includes(n)||hay.includes(nn))out.push(`Mentioned in the guide <button type="button" class="it-link text" data-loot="${esc(s.id)}">${esc(s.name)}</button>`)});
    return out;
  }

  /* ---------- detail pages ---------- */
  function showMaterial(x){
    const m=x.mat,miss=[],where=[];
    const mi=m.map;if(mi&&mi.w)where.push(esc(mi.w));
    if(m.craft&&m.craft.u){const t=m.craft.u.replace(/^Where /,'');const nt=norm(t);if(!where.some(w=>{const nw=norm(w);return nw===nt||nw.includes(nt)||nt.includes(nw)}))where.push(esc(t))}
    const mentions=whereMention(m.name);mentions.forEach(t=>where.push(t));
    const real=where.filter(w=>!GENERIC_WHERE.test(w));
    const hasMap=mi&&mi.m&&mi.m.length>0;
    let whereHtml=bullets(where);
    if(hasMap)whereHtml+=`<div class="it-actions"><span class="it-note">Marked on ${mi.m.length} place${mi.m.length>1?'s':''} on the map.</span><button type="button" class="it-btn" data-showmap="${esc(m.name)}">Show on map</button></div>`;
    if(!real.length&&!hasMap)miss.push('where to find it');
    const ups=m.upgrades;let upHtml='';
    if(ups.length){
      const byLine=new Map();ups.forEach(u=>{if(!byLine.has(u.line.key))byLine.set(u.line.key,[]);byLine.get(u.line.key).push(u)});
      const total=ups.reduce((s,u)=>s+u.q,0);const left=ups.reduce((s,u)=>s+(u.k>=upgDone(u.line)?u.q:0),0);const prog=ups.some(u=>upgDone(u.line)>0);
      upHtml=[...byLine.entries()].map(([k,a])=>`<div class="it-group"><h3>${esc(k)}</h3>${a.map(u=>{const tx=BY.get('t-'+slug(u.t.n))||BY.get('u-'+slug(u.line.key));const done=u.k<upgDone(u.line);return `<span class="it-row${done?' done':''}">${tx?link(tx):esc(u.t.n)}<b class="it-q">×${num(u.q)}</b>${done?'<em>done</em>':''}</span>`}).join('')}</div>`).join('')
        +`<p class="it-total">Total across all upgrades: <b>${num(total)}</b>${prog?` · Still needed for your progress: <b>${num(left)}</b>`:''}</p>`;
    }
    const made=m.usedBy;let madeHtml='';
    if(made.length){
      const byCat=new Map();made.forEach(u=>{if(!byCat.has(u.cat))byCat.set(u.cat,[]);byCat.get(u.cat).push(u)});
      madeHtml=[...byCat.entries()].map(([c,a])=>`<div class="it-group"><h3>${esc(c)}</h3>${a.map(u=>{const gx=BY.get('g-'+slug(u.it.n))||BY.get('m-'+slug(u.it.n));return `<span class="it-row">${gx?link(gx):esc(u.it.n)}<b class="it-q">×${num(u.q)}</b></span>`}).join('')}</div>`).join('')
        +`<p class="it-total">Used in <b>${made.length}</b> recipe${made.length>1?'s':''}.</p>`;
    }
    const craft=m.craft&&m.craft.c.length?`<div class="it-group">${m.craft.c.map(([n,q])=>matLink(n,q)).join('')}</div>`:'';
    const rar=m.craft&&m.craft.r;
    return head(x.icon,m.name,`Material${rar?' · '+rar:''}`)+(m.craft&&m.craft.d?para(m.craft.d):'')
      +sec('Where to find it',whereHtml||para("Where to find it isn't known yet."))
      +sec('How it is made',craft)+sec('Needed for upgrades',upHtml||'<p class="it-none">Not needed for any upgrade.</p>')
      +sec('Gear it makes',madeHtml||'<p class="it-none">Not used in any gear recipe we have.</p>')+missing(miss);
  }
  function head(icon,name,sub,extra){return `<div class="it-head">${icon?`<img src="${icon}" alt="">`:`<span class="it-keyic">${KEY_SVG}</span>`}<div><h2 class="it-name">${esc(name)}</h2><span class="it-sub">${esc(sub)}</span></div>${extra||''}</div>`}
  function showGear(x){
    const it=x.it,miss=[];
    const ingr=it.c.length?`<div class="it-group">${it.c.map(([n,q])=>matLink(n,q)).join('')}</div>`:'';
    if(!it.c.length)miss.push('ingredients');if(!it.d)miss.push('description');if(!it.u)miss.push('how to unlock it');
    const usedIn=GEAR_DATA.flatMap(g=>g.c==='Upgrades'?[]:g.r.filter(r=>r.c.some(([n])=>n===it.n)));
    return head(x.icon,it.n,x.sub)+(it.d?para(it.d):'')
      +sec('How to get it',(it.u?para(it.u):'')+para('Made at the 3D printer.')+(it.cash?`<p class="it-total">Cash cost: <b>$${num(it.cash)}</b></p>`:''))
      +sec('What it needs',ingr||"<p class=\"it-none\">Ingredients aren't known yet.</p>")
      +(usedIn.length?sec('Used to make',`<div class="it-group">${usedIn.map(r=>{const g=BY.get('g-'+slug(r.n));return `<span class="it-row">${g?link(g):esc(r.n)}</span>`}).join('')}</div>`):'')+missing(miss);
  }
  function showKey(x){
    const es=x.entries,miss=[],e=es[0];
    const f=k=>es.map(v=>v[k]).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i);
    const where=f('h'),how=f('w'),areas=f('a2').filter(a=>a!=='Unplaced'),grid=f('g');
    if(!where.length)miss.push('where to use it');if(!how.length)miss.push('how to get it');
    const placed=es.some(v=>!v.nomap&&(v.p||(v.a2&&v.a2!=='Unplaced')));
    if(!placed&&!es[0].nomap)miss.push('its position on the map');
    return head(null,x.name,'Locked door key'+(e.r?' · '+e.r:'')+(areas.length?' · '+areas.join(', '):''))
      +sec('Where to use it',where.map(para).join('')+(grid.length?`<p class="it-note">Map square: ${esc(grid.join(', '))}</p>`:'')+(placed?`<div class="it-actions"><button type="button" class="it-btn" data-showkey="${esc(x.name)}">Show on map</button></div>`:''))
      +sec('How to get the key',how.length?how.map(para).join(''):"<p>How to get it isn't known yet.</p>")+missing(miss);
  }
  function tierRow(t,k,line){const tx=BY.get('t-'+slug(t.n))||BY.get('u-'+slug(line.key));return `<div class="it-tier"><div class="it-tier-h">${tx?link(tx):esc(t.n)}${t.cash?`<b class="it-q">$${num(t.cash)}</b>`:(t.cu?'<em>cash not known yet</em>':'')}</div>${t.d?`<p>${esc(t.d)}</p>`:''}<div class="it-group">${t.c.map(([n,q])=>matLink(n,q)).join('')||`<span class="it-none">${t.cash?'Cash only.':'No materials listed.'}</span>`}</div></div>`}
  function showUpgrade(x){
    const L=x.line,miss=[];
    if(x.isLine){
      const total={},cash=L.tiers.reduce((s,t)=>s+(t.cash||0),0);L.tiers.forEach(t=>t.c.forEach(([n,q])=>total[n]=(total[n]||0)+q));
      const unk=L.tiers.filter(t=>t.cu).length;if(unk)miss.push('cash cost for '+unk+' tier'+(unk>1?'s':''));
      return head(x.icon,L.key,x.sub+' · FOB upgrade')
        +sec('Tiers',L.tiers.map((t,k)=>tierRow(t,k,L)).join(''))
        +sec('Everything this upgrade needs',`<div class="it-group">${Object.entries(total).map(([n,q])=>matLink(n,q)).join('')}</div>${cash?`<p class="it-total">Cash needed: <b>$${num(cash)}</b>${unk?' (more once the missing costs are known)':''}</p>`:''}`)
        +`<div class="it-actions"><button type="button" class="it-btn" data-opentracker="1">Track it in the Upgrades tracker</button></div>`+missing(miss);
    }
    const t=x.tier,k=x.k;if(t.cu)miss.push('cash cost');if(!t.u)miss.push('how to unlock it');
    const prev=L.tiers[k-1],next=L.tiers[k+1],pl=prev&&BY.get('t-'+slug(prev.n)),nl=next&&BY.get('t-'+slug(next.n));
    return head(x.icon,t.n,'Upgrade tier '+(k+1)+' of '+L.tiers.length)+(t.d?para(t.d):'')
      +sec('What it needs',`<div class="it-group">${t.cash?`<span class="it-row"><span>DMZ Cash</span><b class="it-q">$${num(t.cash)}</b></span>`:''}${t.c.map(([n,q])=>matLink(n,q)).join('')}</div>`)
      +(t.u?sec('How to unlock it',para(t.u)):'')+sec('Other tiers',`<div class="it-group">${pl?link(pl):''}${nl?link(nl):''}${BY.get('u-'+slug(L.key))?link(BY.get('u-'+slug(L.key))):''}</div>`)+missing(miss);
  }

  /* ---------- the Items page ---------- */
  function renderItem(id){
    build();const body=$('itBody'),x=BY.get(id);
    if(!x){body.innerHTML=browseHTML();wireBody();document.title='MW4 DMZ Item Search: Where to Find Every Material, Key and Upgrade | NOMADS DMZ HUB';return}
    body.innerHTML=`<article class="it-card">${x.type==='Material'?showMaterial(x):x.type==='Gear'?showGear(x):x.type==='Key'?showKey(x):showUpgrade(x)}</article>`;
    document.title=`${x.name}: where to find it and what it is for | NOMADS DMZ HUB`;wireBody();
  }
  function browseHTML(){
    const group=(h,f)=>{const a=ITEMS.filter(f).sort((p,q)=>p.name.localeCompare(q.name));return `<section class="it-sec"><h2>${h} <em>${a.length}</em></h2><div class="it-browse">${a.map(link).join('')}</div></section>`};
    return `<p class="it-hint">Type a name above, or pick one below.</p>`+group('Materials',x=>x.type==='Material')+group('Gear',x=>x.type==='Gear')+group('Upgrades',x=>x.type==='Upgrade'&&x.isLine)+group('Keys',x=>x.type==='Key');
  }
  function wireBody(){
    const body=$('itBody');
    body.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>openView('items/'+b.dataset.go));
    body.querySelectorAll('[data-boss]').forEach(b=>b.onclick=()=>openView('bosses/'+b.dataset.boss));
    body.querySelectorAll('[data-loot]').forEach(b=>b.onclick=()=>openView('loot/'+b.dataset.loot));
    body.querySelectorAll('[data-showmap]').forEach(b=>b.onclick=()=>{openView('map');requestAnimationFrame(()=>mapShowIngredient(b.dataset.showmap))});
    body.querySelectorAll('[data-showkey]').forEach(b=>b.onclick=()=>{openView('map');requestAnimationFrame(()=>window.mapShowKey&&mapShowKey(b.dataset.showkey))});
    body.querySelectorAll('[data-opentracker]').forEach(b=>b.onclick=()=>openView('upgrades'));
    window.scrollTo(0,0);
  }
  inits.items=function(){
    build();
    const inp=$('isPage'),list=$('isPageList');
    mount(inp,list,x=>openView('items/'+x.id));
    const id=parseRoute().arg;if(id){const x=BY.get(id);if(x)inp.value=x.name}
  };
  window.itemsShow=function(arg){build();const inp=$('isPage');if(inp){const x=BY.get(arg);inp.value=x?x.name:(arg?inp.value:'')}renderItem(arg)};

  /* ---------- the search box on the home page: searches the whole site ---------- */
  const SV=k=>(window.UI_ICONS&&UI_ICONS[k])||'';
  let SITE=null;
  function siteBuild(){
    if(SITE)return;SITE=[];
    const add=(type,name,go,alias,svg,icon)=>{const x={id:'s-'+SITE.length,type,name,go,alias:alias||'',svg:icon?null:svg,icon:icon||null};x.n=norm(name);x.t=x.n.split(' ');x.hay=norm(name+' '+x.alias);SITE.push(x)};
    [['Hajin Map','map','map','map markers exfil sam silo poi locations'],['Loot Hot Spots','loot','loot','loot guides routes vault bunker'],['Upgrades','upgrades','upgrades','upgrade tracker fob'],['Schematic Tracker','schematics','schematics','schematic recipe found blueprint'],['Weapon Manual Tracker','manuals','manuals','weapon manual'],['Camo Tracker','camos','camos','camo challenge'],['Gunsmith','gunsmith','gunsmith','weapon builder attachments build cost'],['Gear Recipes','gear','gear','3d printer crafting recipe'],['Operator Traits','traits','traits','trait tree warfighter scout survivalist prestige'],['Dynamic Ops','dynops','dynops','dynamic operations missions'],['Boss Strats','bosses','bosses','boss lieutenant commander'],['Full Upgrade Item List','upgradeitems','upgradeitems','upgrade items materials list'],['Known Issues and Fixes','patches','patches','patch notes bugs updates']].forEach(([n,v,ic,al])=>add('Page',n,()=>openView(v),al,SV(ic)));
    try{CATALOG.weapons.forEach(w=>add('Weapon',w.name,()=>{openView('gunsmith');const s=$('gsWeapon');if(s&&s.value!==w.id){s.value=w.id;s.dispatchEvent(new Event('change'))}},w.category+' gun weapon',SV('gunsmith')))}catch(e){}
    try{BOSS_STRATS.forEach(b=>add('Boss',b.name,()=>openView('bosses/'+b.id),b.kind+' boss '+(b.location||''),SV('bosses')))}catch(e){}
    try{LOOT_SPOTS.forEach(s=>add('Guide',s.name,()=>openView('loot/'+s.id),'loot guide '+(s.summary||''),SV('loot')))}catch(e){}
    try{DYN_OPS.forEach(o=>add('Op',o.n,()=>openView('dynops'),'dynamic op '+(o.t||''),SV('dynops')))}catch(e){}
    try{const seen=new Set();[].concat(TRAIT_DATA,TRAIT_MINOR,PRESTIGE_TRAITS).forEach(x=>{if(!x||seen.has(x.n))return;seen.add(x.n);add('Trait',x.n,()=>openView('traits'),'trait '+(x.tree||''),SV('traits'),x.ic||null)})}catch(e){}
    try{const seen=new Set();CAMO_WEAPONS.forEach(w=>w.c.forEach(c=>{if(c[0]==='M'||seen.has(c[1]))return;seen.add(c[1]);add('Camo',c[1],()=>openView('camos'),'camo',SV('camos'),c[3]||null)}));CAMO_GLOBAL.forEach(c=>{if(!seen.has(c[1])){seen.add(c[1]);add('Camo',c[1],()=>openView('camos'),'camo mastery',SV('camos'),c[3]||null)}})}catch(e){}
    try{const seen=new Set();MAP_MK.forEach(m=>{const c=MAP_CATS[m[2]];if(!c||c.g!=='Places'||seen.has(m[1]))return;seen.add(m[1]);add('Place',m[1],()=>{openView('map');requestAnimationFrame(()=>window.mapFocus&&mapFocus(m[1]))},'map place location',SV('pin'))})}catch(e){}
  }
  const SITE_ORDER={Page:0,Material:1,Gear:2,Weapon:3,Boss:4,Guide:5,Place:6,Key:7,Upgrade:8,Trait:9,Op:10,Camo:11};
  function siteSearch(q,max=10){
    build();siteBuild();const nq=norm(q);if(!nq)return[];const qt=nq.split(' ');const out=[];
    ITEMS.concat(SITE).forEach(x=>{
      let s=0;
      if(x.n===nq)s=100;else if(x.n.startsWith(nq))s=80;
      else if(qt.every(t=>x.t.some(w=>w.startsWith(t))))s=60;
      else if(nq.length>=4&&x.n.includes(nq))s=45;
      else if(qt.every(t=>x.hay.includes(t))&&nq.length>=3)s=20;
      if(s){if(x.isLine)s+=2;out.push([s-(SITE_ORDER[x.type]||0)*0.4-x.n.length*0.01,x])}
    });
    return out.sort((a,b)=>b[0]-a[0]).slice(0,max).map(a=>a[1]);
  }
  window.siteSearch=siteSearch;
  function homeInit(){
    const inp=$('isHome'),list=$('isHomeList');if(!inp)return;
    const go=x=>{inp.value='';list.hidden=true;inp.setAttribute('aria-expanded','false');if(x.go)x.go();else openView('items/'+x.id)};
    mount(inp,list,go,siteSearch);
    const btn=$('isHomeGo');if(btn)btn.onclick=()=>{const q=inp.value.trim();if(!q){inp.focus();return}const h=siteSearch(q,1)[0];if(h)go(h);else{inp.dispatchEvent(new Event('input'));inp.focus()}};
    inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&list.hidden&&inp.value.trim()){e.preventDefault();btn&&btn.click()}});
  }
  homeInit();

  /* plain-text answers for other pages (tooltips and the Full Upgrade Item List) */
  function whereMentionPlain(name){
    const out=[],n=norm(name),nn=n.replace(/s$/,'');
    BOSS_STRATS.forEach(b=>{const r=norm(b.rewards||'');if(r&&(r.includes(n)||r.includes(nn)))out.push('Possible reward from '+b.name+(b.location?' ('+b.location+')':''))});
    LOOT_SPOTS.forEach(s=>{const hay=norm([s.name,s.summary,s.intro,(s.steps||[]).map(x=>x.h+' '+x.p).join(' ')].join(' '));if(hay.includes(n)||hay.includes(nn))out.push('Mentioned in the loot guide '+s.name)});
    return out;
  }
  window.itemInfo=function(name){
    build();const x=BY.get('m-'+slug(name));if(!x)return null;
    const m=x.mat,where=[],mi=m.map;
    if(mi&&mi.w)where.push(String(mi.w));
    if(m.craft&&m.craft.u){const t=m.craft.u.replace(/^Where /,'');const nt=norm(t);if(!where.some(w=>{const nw=norm(w);return nw===nt||nw.includes(nt)||nt.includes(nw)}))where.push(t)}
    whereMentionPlain(m.name).forEach(t=>where.push(t));
    const words=s=>norm(s).split(' ').filter(w=>w.length>2);
    const similar=(a,b)=>{const A=new Set(words(a)),B=words(b);if(!A.size||!B.length)return false;return B.filter(w=>A.has(w)).length/Math.min(A.size,B.length)>=0.7};
    const real=[];where.filter(w=>!GENERIC_WHERE.test(w)).forEach(w=>{if(!real.some(r=>similar(r,w)))real.push(w)});   // drop lines that say the same thing twice
    return {id:x.id,where:real,hasMap:!!(mi&&mi.m&&mi.m.length),mapCount:mi&&mi.m?mi.m.length:0,craftable:!!(m.craft&&m.craft.c&&m.craft.c.length)};
  };
  window.itemShowOnMap=function(name){openView('map');requestAnimationFrame(()=>mapShowIngredient(name))};
})();

/* ===== FULL UPGRADE ITEM LIST: everything needed for every FOB upgrade, with a counter for what you have ===== */
(function(){
  const UPG=GEAR_DATA.find(g=>g.c==='Upgrades').r;
  const S={q:'',sort:'need',hide:false};
  const stock=()=>{const s=Store.get('upgrades');if(!s.stock)s.stock={};return s.stock};
  const have=n=>Math.max(0,Math.round(+(stock()[n]||0)));
  const CASH_WHERE='Cash has no single place to find it. Dynamic Ops pay 10,000 to 20,000, Side Ops 2,000 and each Mission Step 500.';
  let LIST=null;
  function build(){
    if(LIST)return LIST;const m=new Map();let cash=0,cashTiers=0;
    UPG.forEach(t=>{if(t.cash){cash+=t.cash;cashTiers++}t.c.forEach(([n,q])=>{const r=m.get(n)||{name:n,need:0,uses:0};r.need+=q;r.uses++;m.set(n,r)})});
    LIST=[{name:'DMZ Cash',need:cash,cash:true,uses:cashTiers},...m.values()];return LIST;
  }
  const step=r=>r.cash?10000:1;
  const fmt=(r,n)=>r.cash?'$'+nfmt(n):nfmt(n);
  const wherePlain=r=>{if(r.cash)return [CASH_WHERE];const i=window.itemInfo?itemInfo(r.name):null;return i&&i.where.length?i.where.slice(0,3):[]};
  function rowHTML(r){
    const i=r.cash||!window.itemInfo?null:itemInfo(r.name),w=wherePlain(r),h=have(r.name);
    const ic=r.cash?'<span class="ul-ic cash">$</span>':`<span class="ul-ic"><img src="${ingIcon(r.name)}" alt=""></span>`;
    const name=i?`<button type="button" class="ul-name" data-more>${esc(r.name)}</button>`:`<span class="ul-name">${esc(r.name)}</span>`;
    const acts=(i&&i.hasMap?`<button type="button" class="ul-btn" data-map>Show on map</button>`:'')+(i?`<button type="button" class="ul-btn" data-more>Full details</button>`:'');
    return `<article class="ul-row" data-n="${esc(r.name)}">${ic}
      <div class="ul-main">${name}<div class="ul-where">${w.length?w.map(t=>`<span>${esc(t)}</span>`).join(''):'<span class="ul-unk">Where to find it is not known yet.</span>'}</div>${acts?`<div class="ul-act">${acts}</div>`:''}</div>
      <div class="ul-nd"><span class="ul-lab">Need</span><b>${fmt(r,r.need)}</b></div>
      <div class="ul-hv"><span class="ul-lab">Have</span><div class="ul-step"><button type="button" data-d="-1" aria-label="Fewer ${esc(r.name)}">&minus;</button><input type="number" min="0" inputmode="numeric" value="${h}" aria-label="How many ${esc(r.name)} you have"><button type="button" data-d="1" aria-label="More ${esc(r.name)}">+</button></div></div>
      <div class="ul-lf"><span class="ul-lab">Still need</span><b></b></div><div class="ul-bar" aria-hidden="true"><i></i></div></article>`;
  }
  function paintRow(el,r){
    const h=have(r.name),left=Math.max(0,r.need-h),inp=el.querySelector('input');
    if(document.activeElement!==inp)inp.value=h;
    el.classList.toggle('ok',left===0);el.querySelector('.ul-lf b').textContent=left===0?'Collected':fmt(r,left);
    el.querySelector('.ul-bar i').style.width=Math.min(100,100*h/Math.max(1,r.need))+'%';
  }
  function paintSum(){
    const L=build(),done=L.filter(r=>have(r.name)>=r.need).length;
    document.getElementById('ulSum').innerHTML=`<div class="up-sum"><div><span class="eyebrow">Collected</span><strong>${done} / ${L.length}</strong></div><div class="up-bar big"><i style="width:${100*done/L.length}%"></i></div></div><p class="ul-fine">${L.length-1} different items plus DMZ Cash, across ${UPG.length} upgrade tiers.</p>`;
  }
  function visible(){
    const L=build(),q=S.q.trim().toLowerCase();
    let out=L.filter(r=>(!q||r.name.toLowerCase().includes(q))&&(!S.hide||have(r.name)<r.need));
    const cash=out.filter(r=>r.cash),rest=out.filter(r=>!r.cash);
    const left=r=>Math.max(0,r.need-have(r.name));
    rest.sort(S.sort==='az'?(a,b)=>a.name.localeCompare(b.name):S.sort==='left'?(a,b)=>left(b)-left(a)||a.name.localeCompare(b.name):(a,b)=>b.need-a.need||a.name.localeCompare(b.name));
    return [...cash,...rest];
  }
  function render(){
    const list=document.getElementById('ulList');if(!list)return;if(window.upMigrate)upMigrate();
    const rows=visible();
    list.innerHTML=rows.length?rows.map(rowHTML).join(''):'<p class="ul-empty">Nothing matches. Clear the filter or untick Hide collected.</p>';
    const byName=new Map(build().map(r=>[r.name,r]));
    list.querySelectorAll('.ul-row').forEach(el=>{
      const r=byName.get(el.dataset.n),inp=el.querySelector('input');paintRow(el,r);
      const set=v=>{const n=Math.max(0,Math.min(1e9,Math.round(+v||0)));const s=stock();if(n)s[r.name]=n;else delete s[r.name];Store.save();paintRow(el,r);paintSum()};
      el.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>set(have(r.name)+(+b.dataset.d)*step(r)));
      inp.onchange=()=>set(inp.value);inp.onblur=()=>paintRow(el,r);
      inp.onkeydown=e=>{if(e.key==='Enter')inp.blur()};
      el.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{const i=itemInfo(r.name);if(i)openView('items/'+i.id)});
      const mp=el.querySelector('[data-map]');if(mp)mp.onclick=()=>itemShowOnMap(r.name);
    });
    paintSum();if(window.Account)Account.paintNotes();
  }
  window.upItemsRender=render;
  inits.upgradeitems=function(){
    const $f=document.getElementById('ulFilter'),$s=document.getElementById('ulSort'),$h=document.getElementById('ulHide');
    $f.oninput=()=>{S.q=$f.value;render()};$s.onchange=()=>{S.sort=$s.value;render()};$h.onchange=()=>{S.hide=$h.checked;render()};
    document.getElementById('ulReset').onclick=()=>{if(confirm(Account.user?'Reset all of your counts on this list? It will also reset them in your account.':'Reset all of your counts on this list in this browser?')){Store.get('upgrades').stock={};Store.save();render()}};
    render();
  };
})();

/* ===== Shared tracker page (Schematic Tracker, Weapon Manual Tracker): progress, search, filters, cards ===== */
window.TrackerUI=function(o){
  const el=s=>document.getElementById(o.px+s);
  const TICK='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  let state='all',cat='all',q='';
  const norm=s=>String(s).toLowerCase();
  function paintTop(){
    const L=o.list(),d=L.filter(x=>o.isOn(x.id)).length,t=L.length,pc=t?Math.round(100*d/t):0;
    el('Done').textContent=d+' / '+t;el('Pct').textContent='('+pc+'%)';el('Bar').style.width=(t?100*d/t:0)+'%';
    if(window.tileProgress)tileProgress();
  }
  function chips(){
    const L=o.list(),on=L.filter(x=>o.isOn(x.id)).length;
    const S=[['all','All',L.length],['on',o.onLabel,on],['off',o.offLabel,L.length-on]];
    el('State').innerHTML=S.map(([k,l,n])=>`<button type="button" class="trk-chip${state===k?' on':''}" data-s="${k}" aria-pressed="${state===k}">${esc(l)} (${n})</button>`).join('');
    const cats=[];L.forEach(x=>{if(!cats.includes(x.cat))cats.push(x.cat)});
    el('Cats').innerHTML=[['all',o.allCats||'All categories',L.length]].concat(cats.map(c=>[c,c,L.filter(x=>x.cat===c).length])).map(([k,l,n])=>`<button type="button" class="trk-chip${cat===k?' on':''}" data-c="${esc(k)}" aria-pressed="${cat===k}">${esc(o.catLabel?o.catLabel(l):l)} (${n})</button>`).join('');
    el('State').querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{state=b.dataset.s;chips();grid()});
    el('Cats').querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>{cat=b.dataset.c;chips();grid()});
  }
  function card(x){const on=o.isOn(x.id);return `<button type="button" class="trk-card${on?' on':''}" data-id="${esc(x.id)}" aria-pressed="${on}"><span class="tc-h"><b class="tc-n">${esc(x.name)}</b><small>${esc(o.sub(x))}</small></span><span class="tc-pic">${x.pic?`<img src="${x.pic}" alt="" loading="lazy">`:''}</span><span class="tc-f"><span class="tc-box">${TICK}</span><span class="tc-st">${on?esc(o.onLabel):esc(o.offLabel)}</span></span></button>`}
  function grid(){
    const nq=norm(q.trim()),L=o.list().filter(x=>(cat==='all'||x.cat===cat)&&(state==='all'||(state==='on')===o.isOn(x.id))&&(!nq||norm(x.name+' '+x.cat).includes(nq)));
    const g=el('Grid');g.innerHTML=L.length?L.map(card).join(''):'<p class="up-empty">Nothing matches. Try another search or filter.</p>';
    g.querySelectorAll('.trk-card').forEach(c=>c.onclick=()=>{o.toggle(c.dataset.id);const on=o.isOn(c.dataset.id);c.classList.toggle('on',on);c.setAttribute('aria-pressed',on);c.querySelector('.tc-st').textContent=on?o.onLabel:o.offLabel;paintTop();chips();
      if(state!=='all')setTimeout(grid,350)});
  }
  function render(){chips();grid();paintTop();if(window.Account)Account.paintNotes()}
  function init(){const s=el('Q');if(s)s.oninput=()=>{q=s.value;grid()};render()}
  return {render,init,paintTop};
};

/* ===== SCHEMATIC TRACKER: every recipe that has to be found in Hajin; click one when you have found it ===== */
(function(){
  const slug=s=>String(s).toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
  let LIST=null;
  function list(){
    if(LIST)return LIST;const out=[];
    GEAR_DATA.forEach(g=>{if(g.c==='Upgrades'||g.c==='Ingredients')return;g.r.forEach(it=>{if((it.u||'').startsWith('Find this recipe'))out.push({id:slug(it.n),name:it.n,cat:g.c,rar:it.r||'',pic:it.p||(it.ic&&ING_ICON[it.ic])||ING_GENERIC})})});
    return LIST=out;
  }
  const found=()=>{const s=Store.get('schematics');if(!s.found)s.found={};return s.found};
  window.schematicCounts=()=>{const L=list(),f=found();return [L.filter(x=>f[x.id]).length,L.length]};
  const UI=TrackerUI({px:'sc',list,isOn:id=>!!found()[id],toggle:id=>{const s=found();if(s[id])delete s[id];else s[id]=1;Store.save()},onLabel:'Collected',offLabel:'Missing',sub:x=>x.cat+(x.rar?' · '+x.rar:'')});
  window.scRender=()=>UI.render();
  inits.schematics=function(){
    document.getElementById('scReset').onclick=()=>{if(confirm(Account.user?'Clear every schematic you have ticked? It will also be cleared from your account.':'Clear every schematic you have ticked in this browser?')){Store.get('schematics').found={};Store.save();UI.render()}};
    UI.init();
  };
})();

