/* ===== LATEST COD PATCH NOTES: link-preview card for the newest official MW4 post (found automatically by the Worker) ===== */
(function(){
  const box=document.getElementById('codCard');if(!box)return;
  const INDEX='https://www.callofduty.com/patchnotes';
  // shown until the Worker answers, and kept if it never does
  const FALL={short:'Launch Patch Notes',updated:'2026-10-29',url:INDEX,
    image:'https://imgs.callofduty.com/content/dam/atvi/callofduty/cod-touchui/patchnotes/body/mw4/mp/launch/MW4-00-LAUNCH-PATCH-NOTES-TOUT-C.webp'};
  const ago=iso=>{if(!iso)return '';const t=Date.parse(iso+'T12:00:00Z');if(Number.isNaN(t))return '';const d=Math.floor((Date.now()-t)/864e5);
    if(d<=0)return 'Last updated today';if(d===1)return 'Last updated yesterday';if(d<60)return 'Last updated '+d+' days ago';
    return 'Last updated '+new Date(t).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})};
  const holder=document.getElementById('codImg');let shown='';
  function picture(src){
    if(!src||src===shown)return;shown=src;
    const im=new Image();im.alt='';im.decoding='async';im.referrerPolicy='no-referrer';im.onload=()=>{if(shown===src)holder.replaceChildren(im)};im.src=src;   // if it cannot load, the gold panel stays
  }
  function paint(p){
    document.getElementById('codTitle').textContent=p.short;
    document.getElementById('codWhen').textContent=ago(p.updated);
    document.getElementById('codLink').href=p.url;
    picture(p.image);
  }
  const official=p=>p&&typeof p.url==='string'&&p.url.startsWith(INDEX+'/')&&typeof p.short==='string'&&p.short&&(!p.image||(typeof p.image==='string'&&p.image.startsWith('https://imgs.callofduty.com/')));
  async function latest(){
    const c=new AbortController(),t=setTimeout(()=>c.abort(),8000);
    try{const r=await fetch('/api/cod-latest',{signal:c.signal,headers:{accept:'application/json'}});if(!r.ok)return null;const d=await r.json();return official(d&&d.post)?d.post:null}catch(e){return null}finally{clearTimeout(t)}
  }
  box.classList.add('is-loading');                               // loading placeholder until the Worker answers (or 2.5 seconds)
  paint({...FALL,image:null});                                   // words first; the picture waits for the Worker so only one picture is ever fetched
  let done=false;const wait=setTimeout(()=>{if(!done){box.classList.remove('is-loading');picture(FALL.image)}},2500);
  latest().then(p=>{done=true;clearTimeout(wait);box.classList.remove('is-loading');paint(p?{short:p.short,updated:p.updated||null,url:p.url,image:p.image||FALL.image}:FALL)});
})();

/* ===== HOME EXTRAS: tile progress, phone bar highlight, YouTube banner ===== */
(function(){
  /* ---- progress on the Upgrades and Camo Tracker tiles ---- */
  function counts(){
    let upDone=0,upTotal=0,cmDone=0,cmTotal=0;
    try{
      const UPG=GEAR_DATA.find(g=>g.c==='Upgrades').r,romans=/ ([IVX]+)$/,lines={};
      UPG.forEach(t=>{const k=t.n.replace(romans,'');lines[k]=(lines[k]||0)+1});upTotal=UPG.length;
      const d=(Store.get('upgrades').done)||{};Object.keys(lines).forEach(k=>{upDone+=Math.min(+d[k]||0,lines[k])});
      CAMO_WEAPONS.forEach(w=>{cmTotal+=w.c.length;const f=((Store.get('camos').w)||{})[w.id]||{};cmDone+=Object.keys(f).filter(i=>+i<w.c.length).length});
      cmTotal+=CAMO_GLOBAL.length;cmDone+=Object.keys((Store.get('camos').g)||{}).filter(i=>+i<CAMO_GLOBAL.length).length;
    }catch(e){}
    return {up:[upDone,upTotal],cm:[cmDone,cmTotal]};
  }
  window.tileProgress=function(){
    const c=counts(),set=(k,[d,t],word,suffix)=>{const el=document.querySelector(`[data-prog="${k}"]`);if(!el||!t)return;el.querySelector('i').style.width=(100*d/t)+'%';el.querySelector('.tp-txt').textContent=d+' of '+t+' '+word+' '+(suffix||'done');el.classList.toggle('started',d>0)};
    set('upgrades',c.up,'upgrades');set('camos',c.cm,'camos');if(window.schematicCounts)set('schematics',schematicCounts(),'schematics','found');if(window.manualCounts)set('manuals',manualCounts(),'manuals','found');
  };
  tileProgress();

  /* ---- highlight the current button on the phone bar ---- */
  window.navActive=function(view){document.querySelectorAll('#botNav [data-nav]').forEach(b=>b.classList.toggle('on',b.dataset.nav===(view||'home')))};
  navActive(parseRoute().view);

  /* ---- YouTube banner: the whole banner opens the newest video ---- */
  (async function(){
    const a=document.getElementById('ytBanner');if(!a)return;
    try{
      const c=new AbortController(),t=setTimeout(()=>c.abort(),8000);
      const r=await fetch('/api/latest-video',{signal:c.signal,headers:{accept:'application/json'}});clearTimeout(t);
      if(!r.ok)return;const d=await r.json();const v=d&&d.video;if(!v||!/^[\w-]{11}$/.test(v.id))return;
      a.href='https://www.youtube.com/watch?v='+v.id;
      document.getElementById('ytThumb').style.backgroundImage=`url("https://i.ytimg.com/vi/${v.id}/hqdefault.jpg")`;
      document.getElementById('ytTitle').textContent=v.title;a.classList.add('has-video');
      a.setAttribute('aria-label','Watch the latest video: '+v.title);
      if(window.ytLive)ytLive(v.id);
    }catch(e){}
  })();
})();

/* ===== ACCOUNT: Log in with Discord, and keep Upgrades and Camo progress on every device ===== */
const Account=(function(){
  const NS=['upgrades','camos','schematics','manuals'],LABEL={upgrades:'Upgrades',camos:'Camo Tracker',schematics:'Schematic Tracker',manuals:'Weapon Manual Tracker'};
  const S={configured:false,user:null,status:'',timer:0,busy:false,lastPull:0,retry:0};
  const isO=o=>o&&typeof o==='object'&&!Array.isArray(o);
  const meta=()=>{const m=Store.get('sync');m.rev=m.rev||{};m.dirty=m.dirty||{};return m};
  const snap={};   // what each section looked like the last time it matched the account
  const Pins={list:[],loaded:false,max:200},listeners=[];
  const emit=()=>listeners.forEach(f=>{try{f()}catch(e){}});

  /* ---------- tidy copies of the data, used to compare and to combine ---------- */
  function norm(ns,d){
    d=isO(d)?d:{};const out={};const pos=v=>Math.max(0,Math.round(+v||0));
    if(ns==='upgrades'){out.done={};Object.entries(isO(d.done)?d.done:{}).forEach(([k,v])=>{const n=Math.min(10,pos(v));if(n)out.done[k]=n});
      out.have={};Object.entries(isO(d.have)?d.have:{}).forEach(([t,mats])=>{if(!isO(mats))return;const o={};Object.entries(mats).forEach(([m,v])=>{const n=pos(v);if(n)o[m]=n});if(Object.keys(o).length)out.have[t]=o})
      out.stock={};Object.entries(isO(d.stock)?d.stock:{}).forEach(([k,v])=>{const n=pos(v);if(n)out.stock[k]=n});
      out.spent={};Object.entries(isO(d.spent)?d.spent:{}).forEach(([t,mats])=>{if(!isO(mats))return;const o={};Object.entries(mats).forEach(([m,v])=>{const n=pos(v);if(n)o[m]=n});if(Object.keys(o).length)out.spent[t]=o})}
    else if(ns==='schematics'){out.found={};Object.entries(isO(d.found)?d.found:{}).forEach(([k,v])=>{if(v)out.found[k]=1})}
    else if(ns==='manuals'){out.got={};Object.entries(isO(d.got)?d.got:{}).forEach(([k,v])=>{if(v)out.got[k]=1})}
    else{out.w={};Object.entries(isO(d.w)?d.w:{}).forEach(([id,marks])=>{if(!isO(marks))return;const o={};Object.entries(marks).forEach(([i,v])=>{if(v)o[i]=1});if(Object.keys(o).length)out.w[id]=o});
      out.g={};Object.entries(isO(d.g)?d.g:{}).forEach(([i,v])=>{if(v)out.g[i]=1});
      out.lvl={};Object.entries(isO(d.lvl)?d.lvl:{}).forEach(([id,v])=>{const n=pos(v);if(n)out.lvl[id]=n})}
    return out;
  }
  const canon=o=>JSON.stringify(o,(k,v)=>isO(v)?Object.keys(v).sort().reduce((a,x)=>(a[x]=v[x],a),{}):v);
  const empty=(ns,d)=>{const n=norm(ns,d);return Object.values(n).every(x=>!Object.keys(x).length)};
  function merge(ns,a,b){
    a=norm(ns,a);b=norm(ns,b);const out=JSON.parse(JSON.stringify(a));
    if(ns==='upgrades'){Object.entries(b.done).forEach(([k,v])=>{out.done[k]=Math.max(out.done[k]||0,v)});
      Object.entries(b.have).forEach(([t,mats])=>{out.have[t]=out.have[t]||{};Object.entries(mats).forEach(([m,v])=>{out.have[t][m]=Math.max(out.have[t][m]||0,v)})})
      Object.entries(b.stock).forEach(([k,v])=>{out.stock[k]=Math.max(out.stock[k]||0,v)});
      Object.entries(b.spent).forEach(([t,mats])=>{if(!out.spent[t])out.spent[t]=mats})}
    else if(ns==='schematics'){Object.assign(out.found,b.found)}
    else if(ns==='manuals'){Object.assign(out.got,b.got)}
    else{Object.entries(b.w).forEach(([id,marks])=>{out.w[id]=Object.assign(out.w[id]||{},marks)});Object.assign(out.g,b.g);Object.entries(b.lvl).forEach(([id,v])=>{out.lvl[id]=Math.max(out.lvl[id]||0,v)})}
    return out;
  }

  /* ---------- talking to the site's Worker ---------- */
  async function api(path,o={}){
    try{
      const r=await fetch(path,{credentials:'same-origin',...o,headers:{'content-type':'application/json','x-ndh':'1',...(o.headers||{})}});
      let j=null;try{j=await r.json()}catch(e){}
      return {ok:r.ok,status:r.status,json:j};
    }catch(e){return {ok:false,status:0,json:null}}
  }

  /* ---------- notes that say where progress is saved ---------- */
  function noteText(){
    if(!Store.load()||!Store.ok)return 'This browser is blocking saving, so your progress will be lost when you close the page.';
    if(S.user)return S.status||'Saved to your Discord account. It follows you to every device.';
    if(S.configured)return 'Saved in this browser only. Clearing your browser data removes it.';
    return 'Saved in this browser only. Clearing your browser data removes it.';
  }
  function paintNotes(){
    ['upNote','cmNote','ulNote','scNote','wmNote'].forEach(id=>{const el=document.getElementById(id);if(!el)return;el.textContent=noteText();if(!S.user&&S.configured){const b=document.createElement('button');b.type='button';b.className='acct-link';b.textContent='Log in with Discord';b.onclick=login;el.append(' ',b,' to keep it on every device.')}});
    document.querySelectorAll('[data-savenote]').forEach(el=>{el.textContent=S.user?'Saved to your Discord account.':(S.configured?'Saved in this browser. Log in with Discord to keep it everywhere.':'Saved in this browser only. Clearing your browser data removes it.')});
  }
  const setStatus=t=>{S.status=t;paintNotes();const s=document.getElementById('acctState');if(s)s.textContent=t||'All changes saved.'};

  /* ---------- the button and menu on the home page ---------- */
  const avatarUrl=u=>u&&u.avatar?`https://cdn.discordapp.com/avatars/${u.id}/${u.avatar}.${u.avatar.startsWith('a_')?'gif':'png'}?size=64`:null;
  const DISCORD_SVG='<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="M20.317 4.3698a19.7913 19.7913 0 00-4.8851-1.5152.0741.0741 0 00-.0785.0371c-.211.3753-.4447.8648-.6083 1.2495-1.8447-.2762-3.68-.2762-5.4868 0-.1636-.3933-.4058-.8742-.6177-1.2495a.077.077 0 00-.0785-.037 19.7363 19.7363 0 00-4.8852 1.515.0699.0699 0 00-.0321.0277C.5334 9.0458-.319 13.5799.0992 18.0578a.0824.0824 0 00.0312.0561c2.0528 1.5076 4.0413 2.4228 5.9929 3.0294a.0777.0777 0 00.0842-.0276c.4616-.6304.8731-1.2952 1.226-1.9942a.076.076 0 00-.0416-.1057c-.6528-.2476-1.2743-.5495-1.8722-.8923a.077.077 0 01-.0076-.1277c.1258-.0943.2517-.1923.3718-.2914a.0743.0743 0 01.0776-.0105c3.9278 1.7933 8.18 1.7933 12.0614 0a.0739.0739 0 01.0785.0095c.1202.099.246.1981.3728.2924a.077.077 0 01-.0066.1276 12.2986 12.2986 0 01-1.873.8914.0766.0766 0 00-.0407.1067c.3604.698.7719 1.3628 1.225 1.9932a.076.076 0 00.0842.0286c1.961-.6067 3.9495-1.5219 6.0023-3.0294a.077.077 0 00.0313-.0552c.5004-5.177-.8382-9.6739-3.5485-13.6604a.061.061 0 00-.0312-.0286zM8.02 15.3312c-1.1825 0-2.1569-1.0857-2.1569-2.419 0-1.3332.9555-2.4189 2.157-2.4189 1.2108 0 2.1757 1.0952 2.1568 2.419 0 1.3332-.9555 2.4189-2.1569 2.4189zm7.9748 0c-1.1825 0-2.1569-1.0857-2.1569-2.419 0-1.3332.9554-2.4189 2.1569-2.4189 1.2108 0 2.1757 1.0952 2.1568 2.419 0 1.3332-.946 2.4189-2.1568 2.4189Z"/></svg>';
  function paintChip(){
    const box=document.getElementById('acct');if(!box)return;
    if(!S.configured){box.hidden=true;box.replaceChildren();return}
    box.hidden=false;
    if(!S.user){box.innerHTML=`<button type="button" class="acct-btn login" id="acctLogin">${DISCORD_SVG}<span>Sign in with Discord</span></button>`;document.getElementById('acctLogin').onclick=login;return}
    const av=avatarUrl(S.user);
    box.innerHTML=`<button type="button" class="acct-btn on" id="acctBtn" aria-haspopup="true" aria-expanded="false">${av?`<img src="${av}" alt="" referrerpolicy="no-referrer">`:`<i>${esc(S.user.name.slice(0,1).toUpperCase())}</i>`}<span>${esc(S.user.name)}</span><b aria-hidden="true">▾</b></button>
    <div class="acct-menu" id="acctMenu" role="menu" hidden>
      <div class="am-h">Signed in with Discord</div><div class="am-n">${esc(S.user.name)}</div>
      <div class="am-s" id="acctState">${esc(S.status||'All changes saved.')}</div>
      <a role="menuitem" href="/api/account/export" download>Download my data</a>
      <a role="menuitem" href="/privacy/">What we store</a>
      <button type="button" role="menuitem" id="acctOut">Log out</button>
      <button type="button" role="menuitem" id="acctDel" class="danger">Delete my account</button>
    </div>`;
    const btn=document.getElementById('acctBtn'),menu=document.getElementById('acctMenu');
    const close=()=>{menu.hidden=true;btn.setAttribute('aria-expanded','false')};
    btn.onclick=e=>{e.stopPropagation();const open=menu.hidden;menu.hidden=!open;btn.setAttribute('aria-expanded',open)};
    menu.addEventListener('keydown',e=>{if(e.key==='Escape'){close();btn.focus()}});
    document.getElementById('acctOut').onclick=()=>{close();logoutDialog()};
    document.getElementById('acctDel').onclick=()=>{close();deleteDialog()};
  }

  /* ---------- small dialog used for choices ---------- */
  function dialog({title,body,buttons,focus}){
    return new Promise(resolve=>{
      let d=document.getElementById('acctDlg');if(d)d.remove();d=document.createElement('div');d.id='acctDlg';d.className='acct-dlg';d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-labelledby','acctDlgT');
      d.innerHTML=`<div class="acct-card"><h3 id="acctDlgT">${esc(title)}</h3><div class="acct-body">${body}</div><div class="acct-btns">${buttons.map((b,i)=>`<button type="button" class="acct-b${b.kind?' '+b.kind:''}" data-i="${i}">${esc(b.label)}</button>`).join('')}</div></div>`;
      document.body.appendChild(d);const done=v=>{dialog.last={};d.querySelectorAll('input').forEach(x=>{dialog.last[x.id]=x.value});d.remove();resolve(v)};
      d.querySelectorAll('.acct-b').forEach(b=>b.onclick=()=>done(buttons[+b.dataset.i].value));
      d.addEventListener('keydown',e=>{if(e.key==='Escape'&&buttons.some(b=>b.value==='cancel'))done('cancel')});
      (d.querySelector('[data-i="'+(focus||0)+'"]')||d.querySelector('.acct-b')).focus();
    });
  }

  /* ---------- choosing between this browser and the account ---------- */
  async function conflict(ns,srv){
    const choice=await dialog({title:LABEL[ns]+': two different saves',focus:2,
      body:'<p>Your Discord account already has '+esc(LABEL[ns])+' progress saved, and this browser has different progress.</p><p>Which should we keep?</p><p class="acct-hint">Combine keeps the most progress from both. It is the safe choice if you used the tracker on two devices.</p>',
      buttons:[{label:'Use my account\'s',value:'server'},{label:'Use this browser\'s',value:'local'},{label:'Combine both',value:'merge',kind:'primary'}]});
    const m=meta();
    if(choice==='server')return adopt(ns,srv);
    const data=choice==='merge'?merge(ns,Store.get(ns),srv.data):Store.get(ns);
    if(choice==='merge'){Store.data[ns]=data;Store.save(true)}
    m.rev[ns]=srv.rev;m.dirty[ns]=true;Store.save(true);await push(ns);refreshViews();
  }
  function adopt(ns,srv){const m=meta();Store.data[ns]=srv.data;m.rev[ns]=srv.rev;m.dirty[ns]=false;Store.save(true);snap[ns]=canon(norm(ns,srv.data));refreshViews()}
  function refreshViews(){
    if(window.tileProgress)tileProgress();
    try{if(document.getElementById('screen-upgrades').classList.contains('active')&&window.upRender)upRender()}catch(e){}
    try{if(document.getElementById('screen-camos').classList.contains('active')&&window.cmRender)cmRender()}catch(e){}
    try{if(document.getElementById('screen-schematics').classList.contains('active')&&window.scRender)scRender()}catch(e){}
    try{if(document.getElementById('screen-manuals').classList.contains('active')&&window.wmRender)wmRender()}catch(e){}
    try{if(document.getElementById('screen-upgradeitems').classList.contains('active')&&window.upItemsRender)upItemsRender()}catch(e){}
  }

  /* ---------- saving and loading ---------- */
  async function push(ns){
    const m=meta();setStatus('Saving...');
    const r=await api('/api/sync',{method:'PUT',body:JSON.stringify({ns,baseRev:m.rev[ns]||0,data:Store.get(ns)})});
    if(r.ok){m.rev[ns]=r.json.rev;m.dirty[ns]=false;Store.save(true);snap[ns]=canon(norm(ns,Store.get(ns)));if(!NS.some(n=>m.dirty[n]))setStatus('');return true}
    if(r.status===409){const cur=r.json&&r.json.current;if(!cur){m.rev[ns]=0;Store.save(true);return push(ns)}await conflict(ns,cur);return true}
    if(r.status===429){clearTimeout(S.retry);S.retry=setTimeout(pushDirty,3000);return false}
    if(r.status===401){S.user=null;paintChip();setStatus('');toast('You were logged out. Log in again to keep saving to your account.');return false}
    setStatus('Not saved to your account yet. We will try again.');clearTimeout(S.retry);S.retry=setTimeout(pushDirty,15000);return false;
  }
  async function pushDirty(){
    if(!S.user||S.busy)return;S.busy=true;
    try{for(const ns of NS){if(meta().dirty[ns])await push(ns)}}finally{S.busy=false}
  }
  function changed(){
    if(!S.user)return;const m=meta();let any=false;
    NS.forEach(ns=>{const now=canon(norm(ns,Store.get(ns)));if(now!==snap[ns]){m.dirty[ns]=true;any=true}});
    if(any){Store.save(true);setStatus('Saving...');clearTimeout(S.timer);S.timer=setTimeout(pushDirty,2500)}
  }
  async function reconcile(ns,srv){
    const m=meta(),local=Store.get(ns),has=!empty(ns,local),dirty=!!m.dirty[ns];
    if(!srv){snap[ns]='';if(has){m.dirty[ns]=true;Store.save(true);await push(ns)}return}
    const same=canon(norm(ns,local))===canon(norm(ns,srv.data));
    if(same){m.rev[ns]=srv.rev;m.dirty[ns]=false;Store.save(true);snap[ns]=canon(norm(ns,srv.data));return}
    snap[ns]=snap[ns]||'';
    if(!has)return adopt(ns,srv);
    const known=m.rev[ns]||0;
    if(known===srv.rev){m.dirty[ns]=true;Store.save(true);await push(ns);return}          // only this browser changed it
    if(known>0&&known<srv.rev&&!dirty)return adopt(ns,srv);                             // only another device changed it
    return conflict(ns,srv);                                                            // both changed, or never synced
  }
  async function pull(){
    if(!S.user)return;const r=await api('/api/sync');if(!r.ok)return;
    const m=meta();if(m.user!==S.user.id){m.user=S.user.id;m.rev={};m.dirty={};Store.save(true)}
    for(const ns of NS)await reconcile(ns,r.json&&r.json[ns]);
    S.lastPull=Date.now();paintNotes();
  }


  /* ---------- private map pins ---------- */
  async function loadPins(force){
    if(!S.user)return [];if(Pins.loaded&&!force)return Pins.list;
    const r=await api('/api/pins');if(r.ok&&r.json){Pins.list=r.json.pins||[];Pins.max=r.json.max||200;Pins.loaded=true}return Pins.list;
  }
  async function createPin(p){const r=await api('/api/pins',{method:'POST',body:JSON.stringify(p)});if(r.ok&&r.json&&r.json.pin)Pins.list.push(r.json.pin);return r}
  async function updatePin(id,patch){const r=await api('/api/pins/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify(patch)});if(r.ok&&r.json&&r.json.pin){const i=Pins.list.findIndex(x=>x.id===id);if(i>=0)Pins.list[i]=r.json.pin}return r}
  async function deletePin(id){const r=await api('/api/pins/'+encodeURIComponent(id),{method:'DELETE'});if(r.ok)Pins.list=Pins.list.filter(x=>x.id!==id);return r}

  /* ---------- log in, log out, delete ---------- */
  function login(){location.href='/auth/login'}
  async function logoutDialog(){
    const c=await dialog({title:'Log out?',body:'<p>Your progress stays safe in your account. You can also remove it from this browser, which is a good idea on a shared computer.</p>',
      buttons:[{label:'Cancel',value:'cancel'},{label:'Log out and keep it here',value:'keep'},{label:'Log out and clear this browser',value:'clear',kind:'primary'}]});
    if(c==='cancel')return;
    await api('/auth/logout',{method:'POST',body:'{}'});
    if(c==='clear'){NS.forEach(ns=>{Store.data[ns]={}});}
    const m=meta();m.user=null;m.rev={};m.dirty={};Store.save(true);S.user=null;NS.forEach(ns=>delete snap[ns]);
    Pins.list=[];Pins.loaded=false;paintChip();paintNotes();refreshViews();emit();toast('Logged out.');
  }
  async function deleteDialog(){
    const c=await dialog({title:'Delete my account?',body:'<p>This removes your account, your saved progress and your logins from our database straight away. It cannot be undone.</p><p>Progress saved in this browser is not touched.</p><label class="acct-lab">Type <b>DELETE</b> to confirm<input id="acctDelIn" autocomplete="off" spellcheck="false"></label>',
      buttons:[{label:'Cancel',value:'cancel'},{label:'Delete my account',value:'go',kind:'danger'}]});
    if(c!=='go')return;
    const typed=(dialog.last||{}).acctDelIn;
    if(typed!=='DELETE')return toast('Nothing was deleted. Type DELETE to confirm.');
    const r=await api('/api/account',{method:'DELETE',body:JSON.stringify({confirm:'DELETE'})});
    if(!r.ok)return toast('Could not delete the account. Please try again.');
    const m=meta();m.user=null;m.rev={};m.dirty={};Store.save(true);S.user=null;NS.forEach(ns=>delete snap[ns]);
    Pins.list=[];Pins.loaded=false;paintChip();paintNotes();emit();toast('Your account and its data were deleted.');
  }
  document.addEventListener('click',e=>{const mn=document.getElementById('acctMenu'),bx=document.getElementById('acct');if(mn&&!mn.hidden&&bx&&!bx.contains(e.target)){mn.hidden=true;const b=document.getElementById('acctBtn');if(b)b.setAttribute('aria-expanded','false')}});

  /* ---------- start ---------- */
  async function init(){
    const q=new URLSearchParams(location.search),lg=q.get('login');
    if(lg){history.replaceState(null,'',location.pathname);setTimeout(()=>toast(lg==='ok'?'Logged in with Discord.':lg==='cancelled'?'Login cancelled.':'Login did not work. Please try again.'),400)}
    const r=await api('/api/me',{headers:{}});
    S.configured=!!(r.ok&&r.json&&r.json.configured);S.user=r.ok&&r.json&&r.json.loggedIn?r.json.user:null;
    paintChip();paintNotes();
    emit();
    if(S.user)await pull();
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&S.user&&Date.now()-S.lastPull>60000)pull()});
    window.addEventListener('online',()=>{if(S.user)pushDirty()});
  }
  return {init,changed,noteText,paintNotes,login,loadPins,createPin,updatePin,deletePin,onChange:f=>{listeners.push(f)},get pins(){return Pins},get user(){return S.user},get configured(){return S.configured}};
})();
Account.init();

/* ===== BOSS STRATS ===== */
(function(){
  const ul=$('bossList');
  if(ul){ul.innerHTML=BOSS_STRATS.map(b=>`<li><a class="bs-chip" href="/boss-strats/${b.id}/" data-open="bosses/${b.id}"><img class="bs-th" src="/boss-images/${b.id}.webp" alt="" loading="lazy" data-gone="self"><span><b>${esc(b.name)}</b><i>${esc(b.subtitle)}</i></span></a></li>`).join('');
    ul.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openView(b.dataset.open)}));}
  const c=$('bossCount');if(c)c.textContent=BOSS_STRATS.length+' bosses';
  document.querySelectorAll('.bs-all').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openView('bosses')}));
})();
let bossFilter='All',bossQ='';
document.addEventListener('error',e=>{const im=e.target;if(!(im instanceof HTMLImageElement)||!im.dataset.gone)return;(im.dataset.gone==='parent'?im.parentNode:im).remove()},true);
window.bossShow=function(arg){
  const main=$('bossMain'),b=BOSS_STRATS.find(x=>x.id===arg);
  $('bossSub').textContent=b?b.kind+' // '+b.subtitle:'Strategies for every Lieutenant and Commander';
  const kinds=['All','Lieutenant','Commander'],cnt=k=>k==='All'?BOSS_STRATS.length:BOSS_STRATS.filter(x=>x.kind===k).length;
  const dir=`<section class="box bs-dir"><h2 class="box-h">Boss guide directory</h2><div class="bs-tools"><label class="trk-search"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="M15.5 15.5L21 21"/></svg><input type="search" id="bsQ" placeholder="Search bosses..." aria-label="Search bosses" value="${esc(bossQ)}"></label><div class="trk-chips">${kinds.map(k=>`<button type="button" class="trk-chip${k===bossFilter?' on':''}" data-t="${k}" aria-pressed="${k===bossFilter}">${k==='All'?'All':k+'s'} (${cnt(k)})</button>`).join('')}</div></div><ul class="bs-grid" id="bsGrid"></ul><p class="lt-note">Boss locations, mechanics and drops can change. Spotted a change or have a tip? Tell us in our Discord: discord.gg/nomadoce</p></section>`;
  const url=b?SITE_URL+'/boss-strats/'+b.id+'/':'';
  const det=b?`<section class="box bs-det"><div class="bsd-h"><h1>${esc(b.name)}</h1><span class="bsd-k">${esc(b.kind)}</span><span class="bsd-sub">${esc(b.subtitle)}</span><div class="bsd-act"><button type="button" class="lt-btn" id="bsCopy">Copy link</button>${navigator.share?'<button type="button" class="lt-btn" id="bsShare">Share</button>':''}<button type="button" class="lt-btn ghost bsd-back" id="bsAll">All bosses</button></div></div>
    <div class="bsd-top"><figure class="bsd-pic"><img src="/boss-images/${b.id}.webp" alt="${esc(b.name)}, ${esc(b.subtitle)}" data-gone="parent"></figure>
      <div class="bsd-facts"><div class="bsd-f bsd-loc"><span class="bsd-ic">${(window.UI_ICONS||{}).pin||''}</span><div><h3>Location</h3><p>${esc(b.location)}</p></div>${b.map?'<button type="button" class="lt-btn red" id="bsMap">Show on map</button>':''}</div>
      <div class="bsd-f"><div><h3>Recommended kit</h3><p>${esc(b.loadout)}</p></div></div><div class="bsd-f"><div><h3>Threat</h3><p>${esc(b.threat)}.</p></div></div></div></div>
    <div class="bsd-cols"><div class="bsd-strat"><h2 class="box-h">Strategy</h2><ol class="bsd-steps">${b.steps.map((s,i)=>`<li><span class="bsd-n">${i+1}</span><p>${esc(s)}</p></li>`).join('')}</ol></div>
      <div class="bsd-side"><div class="bsd-box"><h2 class="box-h">Possible rewards</h2><p>${esc(b.rewards)}</p></div><div class="bsd-box"><h2 class="box-h">Top tip</h2><p>${esc(b.tip)}</p></div>${b.note?`<div class="bsd-box"><h2 class="box-h">Field note</h2><p>${esc(b.note)}</p></div>`:''}</div></div></section>`:'';
  main.innerHTML=`<div class="bs-cols${b?' has-det':''}">${dir}${det}</div>`;
  const paintGrid=()=>{const q=bossQ.trim().toLowerCase(),list=BOSS_STRATS.filter(x=>(bossFilter==='All'||x.kind===bossFilter)&&(!q||(x.name+' '+x.location+' '+x.subtitle).toLowerCase().includes(q)));
    $('bsGrid').innerHTML=list.length?list.map(x=>`<li><a class="bs-tile${b&&x.id===b.id?' on':''}" href="/boss-strats/${x.id}/" data-go="${x.id}"${b&&x.id===b.id?' aria-current="page"':''}><span class="bst-img"><img src="/boss-images/${x.id}.webp" alt="" loading="lazy" data-gone="self"></span><span class="bst-k">${esc(x.kind)}</span><strong>${esc(x.name)}</strong></a></li>`).join(''):'<li class="up-empty">No bosses match that search.</li>';
    $('bsGrid').querySelectorAll('[data-go]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openView('bosses/'+a.dataset.go)}))};
  paintGrid();
  $('bsQ').oninput=e=>{bossQ=e.target.value;paintGrid()};
  main.querySelectorAll('.bs-tools .trk-chip').forEach(x=>x.onclick=()=>{bossFilter=x.dataset.t;main.querySelectorAll('.bs-tools .trk-chip').forEach(y=>{y.classList.toggle('on',y===x);y.setAttribute('aria-pressed',y===x)});paintGrid()});
  if(b){const go=(id,fn)=>{const e=$(id);if(e)e.onclick=fn};
    go('bsAll',()=>openView('bosses'));go('bsMap',()=>{openView('map');requestAnimationFrame(()=>window.mapFocus&&mapFocus(b.map))});
    go('bsCopy',()=>copyLink(url));go('bsShare',()=>navigator.share({title:b.name+' strategy',text:b.tip,url}).catch(()=>{}));}
  const sc=main;if(sc)sc.scrollTop=0;window.scrollTo(0,0);
  if(window.placeAbout)setTimeout(placeAbout,0);
};
inits.bosses=function(){};
/* first render once every view is registered (this file loads last) */
render();